window.LAWDATA=window.LAWDATA||{};window.LAWDATA["juki"]={"key":"juki","id":"342AC0000000081","title":"住民基本台帳法","num":"昭和四十二年法律第八十一号","fetched":"2026-11-09","articles":[{"num":"1","title":"第一条","caption":"（目的）","path":["第一章　総則"],"paras":[{"n":"1","s":[{"t":"この法律は、市町村（特別区を含む。以下同じ。）において、住民の居住関係の公証、選挙人名簿の登録その他の住民に関する事務の処理の基礎とするとともに住民の住所に関する届出等の簡素化を図り、あわせて住民に関する記録の適正な管理を図るため、住民に関する記録を正確かつ統一的に行う住民基本台帳の制度を定め、もつて住民の利便を増進するとともに、国及び地方公共団体の行政の合理化に資することを目的とする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"7c93fa418ac3"},{"num":"2","title":"第二条","caption":"（国及び都道府県の責務）","path":["第一章　総則"],"paras":[{"n":"1","s":[{"t":"国及び都道府県は、市町村の住民の住所又は世帯若しくは世帯主の変更及びこれらに伴う住民の権利又は義務の異動その他の住民としての地位の変更に関する市町村長（特別区の区長を含む。以下同じ。）その他の市町村の執行機関に対する届出その他の行為（次条第三項及び第二十一条の四において「住民としての地位の変更に関する届出」と総称する。）が全て一の行為により行われ、かつ、住民に関する事務の処理が全て住民基本台帳に基づいて行われるように、法制上その他必要な措置を講じなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"35630df49cfd"},{"num":"3","title":"第三条","caption":"（市町村長等の責務）","path":["第一章　総則"],"paras":[{"n":"1","s":[{"t":"市町村長は、常に、住民基本台帳を整備し、住民に関する正確な記録が行われるように努めるとともに、住民に関する記録の管理が適正に行われるように必要な措置を講ずるよう努めなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"市町村長その他の市町村の執行機関は、住民基本台帳に基づいて住民に関する事務を管理し、又は執行するとともに、住民からの届出その他の行為に関する事務の処理の合理化に努めなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"住民は、常に、住民としての地位の変更に関する届出を正確に行うように努めなければならず、虚偽の届出その他住民基本台帳の正確性を阻害するような行為をしてはならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"何人も、第十一条第一項に規定する住民基本台帳の一部の写しの閲覧又は第十二条第一項に規定する住民票の写し若しくは住民票記載事項証明書、第十五条の四第一項に規定する除票の写し若しくは除票記載事項証明書、第二十条第一項に規定する戸籍の附票の写し、第二十一条の三第一項に規定する戸籍の附票の除票の写しその他のこの法律の規定により交付される書類の交付により知り得た事項を使用するに当たつて、個人の基本的人権を尊重するよう努めなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a045edadacbf"},{"num":"4","title":"第四条","caption":"（住民の住所に関する法令の規定の解釈）","path":["第一章　総則"],"paras":[{"n":"1","s":[{"t":"住民の住所に関する法令の規定は、地方自治法（昭和二十二年法律第六十七号）第十条第一項に規定する住民の住所と異なる意義の住所を定めるものと解釈してはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"758dc6ce77ef"},{"num":"5","title":"第五条","caption":"（住民基本台帳の備付け）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"市町村は、住民基本台帳を備え、その住民につき、第七条及び第三十条の四十五の規定により記載をすべきものとされる事項を記録するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"344749ddac07"},{"num":"6","title":"第六条","caption":"（住民基本台帳の作成）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"市町村長は、個人を単位とする住民票を世帯ごとに編成して、住民基本台帳を作成しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"市町村長は、適当であると認めるときは、前項の住民票の全部又は一部につき世帯を単位とすることができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"市町村長は、政令で定めるところにより、第一項の住民票を磁気ディスク（これに準ずる方法により一定の事項を確実に記録しておくことができる物を含む。以下同じ。）をもつて調製することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"94d1a6634e0b"},{"num":"7","title":"第七条","caption":"（住民票の記載事項）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"住民票には、次に掲げる事項について記載（前条第三項の規定により磁気ディスクをもつて調製する住民票にあつては、記録。以下同じ。）をする。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"氏名","kind":"plain"}]},{"n":"一の二","s":[{"t":"氏名の振り仮名（戸籍法（昭和二十二年法律第二百二十四号）第十三条第一項第二号に規定する氏名の振り仮名をいう。以下同じ。）","kind":"plain"}]},{"n":"二","s":[{"t":"出生の年月日","kind":"plain"}]},{"n":"三","s":[{"t":"男女の別","kind":"plain"}]},{"n":"四","s":[{"t":"世帯主についてはその旨、世帯主でない者については世帯主の氏名及び世帯主との続柄","kind":"plain"}]},{"n":"五","s":[{"t":"戸籍の表示。","kind":"main"},{"t":"ただし、本籍のない者及び本籍の明らかでない者については、その旨","kind":"proviso"}]},{"n":"六","s":[{"t":"住民となつた年月日","kind":"plain"}]},{"n":"七","s":[{"t":"住所及び一の市町村の区域内において新たに住所を変更した者については、その住所を定めた年月日","kind":"plain"}]},{"n":"八","s":[{"t":"新たに市町村の区域内に住所を定めた者については、その住所を定めた旨の届出の年月日（職権で住民票の記載をした者については、その年月日）及び従前の住所","kind":"plain"}]},{"n":"八の二","s":[{"t":"個人番号（行政手続における特定の個人を識別するための番号の利用等に関する法律（平成二十五年法律第二十七号。以下「番号利用法」という。）第二条第五項に規定する個人番号をいう。以下同じ。）","kind":"plain"}]},{"n":"九","s":[{"t":"選挙人名簿に登録された者については、その旨","kind":"plain"}]},{"n":"十","s":[{"t":"国民健康保険の被保険者（国民健康保険法（昭和三十三年法律第百九十二号）第五条及び第六条の規定による国民健康保険の被保険者をいう。第二十八条及び第三十一条第三項において同じ。）である者については、その資格に関する事項で政令で定めるもの","kind":"plain"}]},{"n":"十の二","s":[{"t":"後期高齢者医療の被保険者（高齢者の医療の確保に関する法律（昭和五十七年法律第八十号）第五十条及び第五十一条の規定による後期高齢者医療の被保険者をいう。第二十八条の二及び第三十一条第三項において同じ。）である者については、その資格に関する事項で政令で定めるもの","kind":"plain"}]},{"n":"十の三","s":[{"t":"介護保険の被保険者（介護保険法（平成九年法律第百二十三号）第九条の規定による介護保険の被保険者（同条第二号に規定する第二号被保険者を除く。）をいう。第二十八条の三及び第三十一条第三項において同じ。）である者については、その資格に関する事項で政令で定めるもの","kind":"plain"}]},{"n":"十一","s":[{"t":"国民年金の被保険者（国民年金法（昭和三十四年法律第百四十一号）第七条その他政令で定める法令の規定による国民年金の被保険者（同条第一項第二号に規定する第二号被保険者及び同項第三号に規定する第三号被保険者を除く。）をいう。第二十九条及び第三十一条第三項において同じ。）である者については、その資格に関する事項で政令で定めるもの","kind":"plain"}]},{"n":"十一の二","s":[{"t":"児童手当の支給を受けている者（児童手当法（昭和四十六年法律第七十三号）第七条の規定により認定を受けた受給資格者（同条第二項に規定する施設等受給資格者にあつては、同項第二号に掲げる里親に限る。）をいう。第二十九条の二及び第三十一条第三項において同じ。）については、その受給資格に関する事項で政令で定めるもの","kind":"plain"}]},{"n":"十二","s":[{"t":"米穀の配給を受ける者（主要食糧の需給及び価格の安定に関する法律（平成六年法律第百十三号）第四十条第一項の規定に基づく政令の規定により米穀の配給が実施される場合におけるその配給に基づき米穀の配給を受ける者で政令で定めるものをいう。第三十条及び第三十一条第三項において同じ。）については、その米穀の配給に関する事項で政令で定めるもの","kind":"plain"}]},{"n":"十三","s":[{"t":"住民票コード（番号、記号その他の符号であつて総務省令で定めるものをいう。以下同じ。）","kind":"plain"}]},{"n":"十四","s":[{"t":"前各号に掲げる事項のほか、政令で定める事項","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"c7658b21f10f"},{"num":"8","title":"第八条","caption":"（住民票の記載等）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"住民票の記載、消除又は記載の修正（以下「住民票の記載等」という。）は、第三十条の三第一項及び第二項、第三十条の四第三項並びに第三十条の五の規定によるほか、政令で定めるところにより、第四章若しくは第四章の四の規定による届出に基づき、又は職権で行うものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"b52708327079"},{"num":"9","title":"第九条","caption":"（住民票の記載等のための市町村長間の通知）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"市町村長は、他の市町村から当該市町村の区域内に住所を変更した者につき住民票の記載をしたときは、遅滞なく、その旨を当該他の市町村の市町村長に通知しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"市町村長は、その市町村の住民以外の者について戸籍に関する届書、申請書その他の書類を受理し、又は職権で戸籍の記載若しくは記録をした場合において、その者の住所地で住民票の記載等をすべきときは、遅滞なく、当該住民票の記載等をすべき事項をその住所地の市町村長に通知しなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前二項の規定による通知は、総務省令（前項の規定による通知にあつては、総務省令・法務省令。以下この項において同じ。）で定めるところにより、市町村長の使用に係る電子計算機（入出力装置を含む。以下同じ。）から電気通信回線を通じて相手方である他の市町村の市町村長の使用に係る電子計算機に送信することによつて行うものとする。","kind":"main"},{"t":"ただし、総務省令で定める場合にあつては、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"48c3ce2acc53"},{"num":"10","title":"第十条","caption":"（選挙人名簿の登録等に関する選挙管理委員会の通知）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"市町村の選挙管理委員会は、公職選挙法（昭和二十五年法律第百号）第二十二条第一項若しくは第三項、第二十四条第二項若しくは第二十六条の規定により選挙人名簿に登録したとき、又は同項若しくは同法第二十八条の規定により選挙人名簿から抹消したときは、遅滞なく、その旨を当該市町村の市町村長に通知しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"6c30b72ae660"},{"num":"10_2","title":"第十条の二","caption":"（住民票の改製）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"市町村長は、必要があると認めるときは、住民票を改製することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"f58cb8d79c7e"},{"num":"11","title":"第十一条","caption":"（国又は地方公共団体の機関の請求による住民基本台帳の一部の写しの閲覧）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"国又は地方公共団体の機関は、法令で定める事務の遂行のために必要である場合には、市町村長に対し、当該市町村が備える住民基本台帳のうち第七条第一号から第三号まで及び第七号に掲げる事項（同号に掲げる事項については、住所とする。以下この項において同じ。）に係る部分の写し（第六条第三項の規定により磁気ディスクをもつて住民票を調製することにより住民基本台帳を作成している市町村にあつては、当該住民基本台帳に記録されている事項のうち第七条第一号から第三号まで及び第七号に掲げる事項を記載した書類。以下この条、次条及び第五十条において「住民基本台帳の一部の写し」という。）を当該国又は地方公共団体の機関の職員で当該国又は地方公共団体の機関が指定するものに閲覧させることを請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定による請求は、総務省令で定めるところにより、次に掲げる事項を明らかにしてしなければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"当該請求をする国又は地方公共団体の機関の名称","kind":"plain"}]},{"n":"二","s":[{"t":"請求事由（当該請求が犯罪捜査に関するものその他特別の事情により請求事由を明らかにすることが事務の性質上困難であるもの（次項において「犯罪捜査等のための請求」という。）にあつては、法令で定める事務の遂行のために必要である旨及びその根拠となる法令の名称）","kind":"plain"}]},{"n":"三","s":[{"t":"住民基本台帳の一部の写しを閲覧する者の職名及び氏名","kind":"plain"}]},{"n":"四","s":[{"t":"前三号に掲げるもののほか、総務省令で定める事項","kind":"plain"}]}]},{"n":"３","s":[{"t":"市町村長は、毎年少なくとも一回、第一項の規定による請求に係る住民基本台帳の一部の写しの閲覧（犯罪捜査等のための請求に係るものを除く。）の状況について、当該請求をした国又は地方公共団体の機関の名称、請求事由の概要その他総務省令で定める事項を公表するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"31ffa939ca65"},{"num":"11_2","title":"第十一条の二","caption":"（個人又は法人の申出による住民基本台帳の一部の写しの閲覧）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"市町村長は、次に掲げる活動を行うために住民基本台帳の一部の写しを閲覧することが必要である旨の申出があり、かつ、当該申出を相当と認めるときは、当該申出を行う者（以下この条及び第五十条において「申出者」という。）が個人の場合にあつては当該申出者又はその指定する者に、当該申出者が法人（法人でない団体で代表者又は管理人の定めのあるものを含む。以下この条及び第十二条の三第四項において同じ。）の場合にあつては当該法人の役職員又は構成員（他の法人と共同して申出をする場合にあつては、当該他の法人の役職員又は構成員を含む。）で当該法人が指定するものに、その活動に必要な限度において、住民基本台帳の一部の写しを閲覧させることができる。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"統計調査、世論調査、学術研究その他の調査研究のうち、総務大臣が定める基準に照らして公益性が高いと認められるものの実施","kind":"plain"}]},{"n":"二","s":[{"t":"公共的団体が行う地域住民の福祉の向上に寄与する活動のうち、公益性が高いと認められるものの実施","kind":"plain"}]},{"n":"三","s":[{"t":"営利以外の目的で行う居住関係の確認のうち、訴訟の提起その他特別の事情による居住関係の確認として市町村長が定めるものの実施","kind":"plain"}]}]},{"n":"２","s":[{"t":"前項の申出は、総務省令で定めるところにより、次に掲げる事項を明らかにしてしなければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"申出者の氏名及び住所（申出者が法人の場合にあつては、その名称、代表者又は管理人の氏名及び主たる事務所の所在地）","kind":"plain"}]},{"n":"二","s":[{"t":"住民基本台帳の一部の写しの閲覧により知り得た事項（以下この条及び第五十条において「閲覧事項」という。）の利用の目的","kind":"plain"}]},{"n":"三","s":[{"t":"住民基本台帳の一部の写しを閲覧する者（以下この条及び第五十条において「閲覧者」という。）の氏名及び住所","kind":"plain"}]},{"n":"四","s":[{"t":"閲覧事項の管理の方法","kind":"plain"}]},{"n":"五","s":[{"t":"申出者が法人の場合にあつては、当該法人の役職員又は構成員のうち閲覧事項を取り扱う者の範囲","kind":"plain"}]},{"n":"六","s":[{"t":"前項第一号に掲げる活動に係る申出の場合にあつては、調査研究の成果の取扱い","kind":"plain"}]},{"n":"七","s":[{"t":"前各号に掲げるもののほか、総務省令で定める事項","kind":"plain"}]}]},{"n":"３","s":[{"t":"個人である申出者は、前項第二号に掲げる利用の目的（以下この条及び第五十条において「利用目的」という。）を達成するために当該申出者及び閲覧者以外の者に閲覧事項を取り扱わせることが必要な場合には、第一項の申出をする際に、その旨並びに閲覧事項を取り扱う者として当該申出者が指定する者の氏名及び住所をその市町村長に申し出ることができる。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"前項の規定による申出を受けた市町村長は、当該申出に相当な理由があると認めるときは、その申出を承認することができる。","kind":"plain"},{"t":"この場合において、当該承認を受けた申出者は、当該申出者が指定した者（当該承認を受けた者に限る。以下この条及び第五十条において「個人閲覧事項取扱者」という。）にその閲覧事項を取り扱わせることができる。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"法人である申出者は、閲覧者及び第二項第五号に掲げる範囲に属する者のうち当該申出者が指定するもの（以下この条及び第五十条において「法人閲覧事項取扱者」という。）以外の者にその閲覧事項を取り扱わせてはならない。","kind":"plain"}],"items":[]},{"n":"６","s":[{"t":"申出者は、閲覧者、個人閲覧事項取扱者又は法人閲覧事項取扱者による閲覧事項の漏えいの防止その他の閲覧事項の適切な管理のために必要な措置を講じなければならない。","kind":"plain"}],"items":[]},{"n":"７","s":[{"t":"申出者、閲覧者、個人閲覧事項取扱者又は法人閲覧事項取扱者は、本人の事前の同意を得ないで、当該閲覧事項を利用目的以外の目的のために利用し、又は当該閲覧事項に係る申出者、閲覧者、個人閲覧事項取扱者及び法人閲覧事項取扱者以外の者に提供してはならない。","kind":"plain"}],"items":[]},{"n":"８","s":[{"t":"市町村長は、閲覧者若しくは申出者が偽りその他不正の手段により第一項の規定による住民基本台帳の一部の写しの閲覧をし、若しくはさせた場合又は申出者、閲覧者、個人閲覧事項取扱者若しくは法人閲覧事項取扱者が前項の規定に違反した場合において、個人の権利利益を保護するため必要があると認めるときは、当該閲覧事項に係る申出者、当該閲覧をし、若しくはさせた者又は当該違反行為をした者に対し、当該閲覧事項が利用目的以外の目的で利用され、又は当該閲覧事項に係る申出者、閲覧者、個人閲覧事項取扱者及び法人閲覧事項取扱者以外の者に提供されないようにするための措置を講ずることを勧告することができる。","kind":"plain"}],"items":[]},{"n":"９","s":[{"t":"市町村長は、前項の規定による勧告を受けた者が正当な理由がなくてその勧告に係る措置を講じなかつた場合において、個人の権利利益が不当に侵害されるおそれがあると認めるときは、その者に対し、その勧告に係る措置を講ずることを命ずることができる。","kind":"plain"}],"items":[]},{"n":"１０","s":[{"t":"市町村長は、前二項の規定にかかわらず、閲覧者若しくは申出者が偽りその他不正の手段により第一項の規定による住民基本台帳の一部の写しの閲覧をし、若しくはさせた場合又は申出者、閲覧者、個人閲覧事項取扱者若しくは法人閲覧事項取扱者が第七項の規定に違反した場合において、個人の権利利益が不当に侵害されることを防止するため特に措置を講ずる必要があると認めるときは、当該閲覧事項に係る申出者、当該閲覧をし、若しくはさせた者又は当該違反行為をした者に対し、当該閲覧事項が利用目的以外の目的で利用され、又は当該閲覧事項に係る申出者、閲覧者、個人閲覧事項取扱者及び法人閲覧事項取扱者以外の者に提供されないようにするための措置を講ずることを命ずることができる。","kind":"plain"}],"items":[]},{"n":"１１","s":[{"t":"市町村長は、この条の規定の施行に必要な限度において、申出者に対し、必要な報告をさせることができる。","kind":"plain"}],"items":[]},{"n":"１２","s":[{"t":"市町村長は、毎年少なくとも一回、第一項の申出に係る住民基本台帳の一部の写しの閲覧（同項第三号に掲げる活動に係るものを除く。）の状況について、申出者の氏名（申出者が法人の場合にあつては、その名称及び代表者又は管理人の氏名）、利用目的の概要その他総務省令で定める事項を公表するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"73fdb96c2f0f"},{"num":"12","title":"第十二条","caption":"（本人等の請求による住民票の写し等の交付）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"市町村が備える住民基本台帳に記録されている者（当該市町村の市町村長がその者が属していた世帯について世帯を単位とする住民票を作成している場合にあつては、当該住民票から除かれた者（その者に係る全部の記載が市町村長の過誤によつてされ、かつ、当該記載が消除された者を除く。）を含む。次条第一項において同じ。）は、当該市町村の市町村長に対し、自己又は自己と同一の世帯に属する者に係る住民票の写し（第六条第三項の規定により磁気ディスクをもつて住民票を調製している市町村にあつては、当該住民票に記録されている事項を記載した書類。以下同じ。）又は住民票に記載をした事項に関する証明書（以下「住民票記載事項証明書」という。）の交付を請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定による請求は、総務省令で定めるところにより、次に掲げる事項を明らかにしてしなければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"当該請求をする者の氏名及び住所","kind":"plain"}]},{"n":"二","s":[{"t":"現に請求の任に当たつている者が、請求をする者の代理人であるときその他請求をする者と異なる者であるときは、当該請求の任に当たつている者の氏名及び住所","kind":"plain"}]},{"n":"三","s":[{"t":"当該請求の対象とする者の氏名","kind":"plain"}]},{"n":"四","s":[{"t":"前三号に掲げるもののほか、総務省令で定める事項","kind":"plain"}]}]},{"n":"３","s":[{"t":"第一項の規定による請求をする場合において、現に請求の任に当たつている者は、市町村長に対し、個人番号カード（番号利用法第二条第七項に規定する個人番号カードをいう。以下同じ。）を提示する方法その他の総務省令で定める方法により、当該請求の任に当たつている者が本人であることを明らかにしなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"前項の場合において、現に請求の任に当たつている者が、請求をする者の代理人であるときその他請求をする者と異なる者であるときは、当該請求の任に当たつている者は、市町村長に対し、総務省令で定める方法により、請求をする者の依頼により又は法令の規定により当該請求の任に当たるものであることを明らかにする書類を提示し、又は提出しなければならない。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"市町村長は、特別の請求がない限り、第一項に規定する住民票の写しの交付の請求があつたときは、第七条第四号、第五号及び第八号の二から第十四号までに掲げる事項の全部又は一部の記載を省略した同項に規定する住民票の写しを交付することができる。","kind":"plain"}],"items":[]},{"n":"６","s":[{"t":"市町村長は、第一項の規定による請求が不当な目的によることが明らかなときは、これを拒むことができる。","kind":"plain"}],"items":[]},{"n":"７","s":[{"t":"第一項の規定による請求をしようとする者は、郵便その他の総務省令で定める方法により、同項に規定する住民票の写し又は住民票記載事項証明書の送付を求めることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"25684c4f5efb"},{"num":"12_2","title":"第十二条の二","caption":"（国又は地方公共団体の機関の請求による住民票の写し等の交付）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"国又は地方公共団体の機関は、法令で定める事務の遂行のために必要である場合には、市町村長に対し、当該市町村が備える住民基本台帳に記録されている者に係る住民票の写しで第七条第八号の二及び第十三号に掲げる事項の記載を省略したもの又は住民票記載事項証明書で同条第一号から第八号まで、第九号から第十二号まで及び第十四号に掲げる事項に関するものの交付を請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定による請求は、総務省令で定めるところにより、次に掲げる事項を明らかにしてしなければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"当該請求をする国又は地方公共団体の機関の名称","kind":"plain"}]},{"n":"二","s":[{"t":"現に請求の任に当たつている者の職名及び氏名","kind":"plain"}]},{"n":"三","s":[{"t":"当該請求の対象とする者の氏名及び住所","kind":"plain"}]},{"n":"四","s":[{"t":"請求事由（当該請求が犯罪捜査に関するものその他特別の事情により請求事由を明らかにすることが事務の性質上困難であるものにあつては、法令で定める事務の遂行のために必要である旨及びその根拠となる法令の名称）","kind":"plain"}]},{"n":"五","s":[{"t":"前各号に掲げるもののほか、総務省令で定める事項","kind":"plain"}]}]},{"n":"３","s":[{"t":"第一項の規定による請求をする場合において、現に請求の任に当たつている者は、市町村長に対し、国又は地方公共団体の機関の職員であることを示す書類を提示する方法その他の総務省令で定める方法により、当該請求の任に当たつている者が本人であることを明らかにしなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"市町村長は、特別の請求がない限り、第一項に規定する住民票の写しの交付の請求があつたときは、第七条第四号、第五号、第九号から第十二号まで及び第十四号に掲げる事項の全部又は一部の記載を省略した同項に規定する住民票の写しを交付することができる。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"第一項の規定による請求をしようとする国又は地方公共団体の機関は、郵便その他の総務省令で定める方法により、同項に規定する住民票の写し又は住民票記載事項証明書の送付を求めることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"f23b12e10c37"},{"num":"12_3","title":"第十二条の三","caption":"（本人等以外の者の申出による住民票の写し等の交付）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"市町村長は、前二条の規定によるもののほか、当該市町村が備える住民基本台帳について、次に掲げる者から、住民票の写しで基礎証明事項（第七条第一号から第三号まで及び第六号から第八号までに掲げる事項をいう。以下この項及び第七項において同じ。）のみが表示されたもの又は住民票記載事項証明書で基礎証明事項に関するものが必要である旨の申出があり、かつ、当該申出を相当と認めるときは、当該申出をする者に当該住民票の写し又は住民票記載事項証明書を交付することができる。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"自己の権利を行使し、又は自己の義務を履行するために住民票の記載事項を確認する必要がある者","kind":"plain"}]},{"n":"二","s":[{"t":"国又は地方公共団体の機関に提出する必要がある者","kind":"plain"}]},{"n":"三","s":[{"t":"前二号に掲げる者のほか、住民票の記載事項を利用する正当な理由がある者","kind":"plain"}]}]},{"n":"２","s":[{"t":"市町村長は、前二条及び前項の規定によるもののほか、当該市町村が備える住民基本台帳について、特定事務受任者から、受任している事件又は事務の依頼者が同項各号に掲げる者に該当することを理由として、同項に規定する住民票の写し又は住民票記載事項証明書が必要である旨の申出があり、かつ、当該申出を相当と認めるときは、当該特定事務受任者に当該住民票の写し又は住民票記載事項証明書を交付することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前項に規定する「特定事務受任者」とは、弁護士（弁護士法人及び弁護士・外国法事務弁護士共同法人を含む。）、司法書士（司法書士法人を含む。）、土地家屋調査士（土地家屋調査士法人を含む。）、税理士（税理士法人を含む。）、社会保険労務士（社会保険労務士法人を含む。）、弁理士（弁理士法人を含む。）、海事代理士又は行政書士（行政書士法人を含む。）をいう。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"第一項又は第二項の申出は、総務省令で定めるところにより、次に掲げる事項を明らかにしてしなければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"申出者（第一項又は第二項の申出をする者をいう。以下この条において同じ。）の氏名及び住所（申出者が法人の場合にあつては、その名称、代表者又は管理人の氏名及び主たる事務所の所在地）","kind":"plain"}]},{"n":"二","s":[{"t":"現に申出の任に当たつている者が、申出者の代理人であるときその他申出者と異なる者であるときは、当該申出の任に当たつている者の氏名及び住所","kind":"plain"}]},{"n":"三","s":[{"t":"当該申出の対象とする者の氏名及び住所","kind":"plain"}]},{"n":"四","s":[{"t":"第一項に規定する住民票の写し又は住民票記載事項証明書の利用の目的","kind":"plain"}]},{"n":"五","s":[{"t":"第二項の申出の場合にあつては、前項に規定する特定事務受任者の受任している事件又は事務についての資格及び業務の種類並びに依頼者の氏名又は名称（当該受任している事件又は事務についての業務が裁判手続又は裁判外手続における民事上若しくは行政上の紛争処理の手続についての代理業務その他の政令で定める業務であるときは、当該事件又は事務についての資格及び業務の種類）","kind":"plain"}]},{"n":"六","s":[{"t":"前各号に掲げるもののほか、総務省令で定める事項","kind":"plain"}]}]},{"n":"５","s":[{"t":"第一項又は第二項の申出をする場合において、現に申出の任に当たつている者は、市町村長に対し、個人番号カードを提示する方法その他の総務省令で定める方法により、当該申出の任に当たつている者が本人であることを明らかにしなければならない。","kind":"plain"}],"items":[]},{"n":"６","s":[{"t":"前項の場合において、現に申出の任に当たつている者が、申出者の代理人であるときその他申出者と異なる者であるときは、当該申出の任に当たつている者は、市町村長に対し、総務省令で定める方法により、申出者の依頼により又は法令の規定により当該申出の任に当たるものであることを明らかにする書類を提示し、又は提出しなければならない。","kind":"plain"}],"items":[]},{"n":"７","s":[{"t":"申出者は、第四項第四号に掲げる利用の目的を達成するため、基礎証明事項のほか基礎証明事項以外の事項（第七条第八号の二及び第十三号に掲げる事項を除く。以下この項において同じ。）の全部若しくは一部が表示された住民票の写し又は基礎証明事項のほか基礎証明事項以外の事項の全部若しくは一部を記載した住民票記載事項証明書が必要である場合には、第一項又は第二項の申出をする際に、その旨を市町村長に申し出ることができる。","kind":"plain"}],"items":[]},{"n":"８","s":[{"t":"市町村長は、前項の規定による申出を相当と認めるときは、第一項に規定する住民票の写し又は住民票記載事項証明書に代えて、前項に規定する住民票の写し又は住民票記載事項証明書を交付することができる。","kind":"plain"}],"items":[]},{"n":"９","s":[{"t":"第一項又は第二項の申出をしようとする者は、郵便その他の総務省令で定める方法により、第一項に規定する住民票の写し又は住民票記載事項証明書の送付を求めることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"973fb91dba6c"},{"num":"12_4","title":"第十二条の四","caption":"（本人等の請求に係る住民票の写しの交付の特例）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"住民基本台帳に記録されている者は、その者が記録されている住民基本台帳を備える市町村の市町村長（以下この条において「住所地市町村長」という。）以外の市町村長に対し、自己又は自己と同一の世帯に属する者に係る住民票の写しで第七条第五号、第九号から第十二号まで及び第十四号に掲げる事項の記載を省略したものの交付を請求することができる。","kind":"plain"},{"t":"この場合において、当該請求をする者は、総務省令で定めるところにより、個人番号カード又は総務省令で定める書類を提示してこれをしなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の請求を受けた市町村長（以下この条において「交付地市町村長」という。）は、政令で定める事項を同項の請求をした者の住所地市町村長に通知しなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前項の規定による通知を受けた住所地市町村長は、政令で定める事項を交付地市町村長に通知しなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"前項の規定による通知を受けた交付地市町村長は、政令で定めるところにより、第一項の請求に係る住民票の写しを作成して、同項の請求をした者に交付するものとする。","kind":"plain"},{"t":"この場合において、交付地市町村長は、特別の請求がない限り、第七条第四号、第八号の二及び第十三号に掲げる事項の全部又は一部の記載を省略した同項に規定する住民票の写しを交付することができる。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"第二項又は第三項の規定による通知は、総務省令で定めるところにより、交付地市町村長又は住所地市町村長の使用に係る電子計算機から電気通信回線を通じて相手方である住所地市町村長又は交付地市町村長の使用に係る電子計算機に送信することによつて行うものとする。","kind":"plain"}],"items":[]},{"n":"６","s":[{"t":"第十二条第二項（第二号を除く。）及び第六項の規定は、第一項の規定による請求について準用する。","kind":"plain"},{"t":"この場合において、同条第六項中「市町村長」とあるのは、「第十二条の四第二項に規定する交付地市町村長」と読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"3564d93f4cc5"},{"num":"12_5","title":"第十二条の五","caption":"（住民基本台帳の脱漏等に関する都道府県知事の通報）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"都道府県知事は、その事務を管理し、又は執行するに当たつて、当該都道府県の区域内の市町村の住民基本台帳に脱漏若しくは誤載があり、又は住民票に誤記若しくは記載漏れがあることを知つたときは、遅滞なく、その旨を当該住民基本台帳を備える市町村の市町村長に通報しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"96ab37477cef"},{"num":"13","title":"第十三条","caption":"（住民基本台帳の脱漏等に関する委員会の通報）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"市町村の委員会（地方自治法第百三十八条の四第一項に規定する委員会をいう。第二十条の三において同じ。）は、その事務を管理し、又は執行するに当たつて、住民基本台帳に脱漏若しくは誤載があり、又は住民票に誤記若しくは記載漏れがあると認めるときは、遅滞なく、その旨を当該市町村の市町村長に通報しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"f67d58c67cdd"},{"num":"14","title":"第十四条","caption":"（住民基本台帳の正確な記録を確保するための措置）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"市町村長は、その事務を管理し、及び執行することにより、又は第十条若しくは前二条の規定による通知若しくは通報若しくは第三十四条第一項若しくは第二項の調査によつて、住民基本台帳に脱漏若しくは誤載があり、又は住民票に誤記若しくは記載漏れがあることを知つたときは、届出義務者に対する届出の催告その他住民基本台帳の正確な記録を確保するため必要な措置を講じなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"住民基本台帳に記録されている者は、自己又は自己と同一の世帯に属する者に係る住民票に誤記又は記載漏れがあることを知つたときは、その者が記録されている住民基本台帳を備える市町村の市町村長に対してその旨を申し出ることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"9ed06db2ffdd"},{"num":"15","title":"第十五条","caption":"（選挙人名簿との関係）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"選挙人名簿の登録は、住民基本台帳に記録されている者又は公職選挙法第二十一条第二項に規定する住民基本台帳に記録されていた者で選挙権を有するものについて行うものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"市町村長は、第八条の規定により住民票の記載等をしたときは、遅滞なく、当該住民票の記載等で選挙人名簿の登録に関係がある事項を当該市町村の選挙管理委員会に通知しなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"市町村の選挙管理委員会は、前項の規定により通知された事項を不当な目的に使用されることがないよう努めなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ba46b0a04a46"},{"num":"15_2","title":"第十五条の二","caption":"（除票簿）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"市町村長は、住民票（世帯を単位とする住民票にあつては、その全部）を消除したとき、又は住民票を改製したときは、その消除した住民票又は改製前の住民票（以下「除票」と総称する。）を住民基本台帳から除いて別につづり、除票簿として保存しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"第六条第三項の規定により磁気ディスクをもつて住民票を調製している市町村にあつては、磁気ディスクをもつて調製した除票を蓄積して除票簿とすることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e2c3316d936a"},{"num":"15_3","title":"第十五条の三","caption":"（除票の記載事項）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"除票には、当該除票に係る住民票に記載をしていた事項のほか、当該住民票を消除した事由（転出（市町村の区域外へ住所を移すことをいう。以下同じ。）の場合にあつては、転出により消除した旨及び転出先の住所）及びその事由の生じた年月日（第二十四条の規定による届出に基づき住民票を消除した場合にあつては、転出の予定年月日）又は改製した旨及びその年月日の記載（前条第二項の規定により磁気ディスクをもつて調製する除票にあつては、記録。以下同じ。）をする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"第九条第一項の規定による通知を受けた市町村長は、当該通知に係る除票に転出をした旨の記載をする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"52707c732c77"},{"num":"15_4","title":"第十五条の四","caption":"（除票の写し等の交付）","path":["第二章　住民基本台帳"],"paras":[{"n":"1","s":[{"t":"市町村が保存する除票に記載されている者は、当該市町村の市町村長に対し、その者に係る除票の写し（第十五条の二第二項の規定により磁気ディスクをもつて除票を調製している市町村にあつては、当該除票に記録されている事項を記載した書類。次項及び第三項並びに第四十六条第二号において同じ。）又は除票に記載をした事項に関する証明書（次項及び第三項並びに同号において「除票記載事項証明書」という。）の交付を請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"国又は地方公共団体の機関は、法令で定める事務の遂行のために必要である場合には、市町村長に対し、当該市町村が保存する除票の写しで第七条第八号の二及び第十三号に掲げる事項の記載を省略したもの又は除票記載事項証明書で同条第一号から第八号まで、第九号から第十二号まで及び第十四号に掲げる事項その他政令で定める事項に関するものの交付を請求することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"市町村長は、前二項の規定によるもののほか、当該市町村が保存する除票について、次に掲げる者から、除票の写しで除票基礎証明事項（第七条第一号から第三号まで及び第六号から第八号までに掲げる事項その他政令で定める事項をいう。以下この項において同じ。）のみが表示されたもの又は除票記載事項証明書で除票基礎証明事項に関するものが必要である旨の申出があり、かつ、当該申出を相当と認めるときは、当該申出をする者に当該除票の写し又は除票記載事項証明書を交付することができる。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"自己の権利を行使し、又は自己の義務を履行するために除票の記載事項を確認する必要がある者","kind":"plain"}]},{"n":"二","s":[{"t":"国又は地方公共団体の機関に提出する必要がある者","kind":"plain"}]},{"n":"三","s":[{"t":"前二号に掲げる者のほか、除票の記載事項を利用する正当な理由がある者","kind":"plain"}]}]},{"n":"４","s":[{"t":"市町村長は、前三項の規定によるもののほか、当該市町村が保存する除票について、第十二条の三第三項に規定する特定事務受任者から、受任している事件又は事務の依頼者が前項各号に掲げる者に該当することを理由として、同項に規定する除票の写し又は除票記載事項証明書が必要である旨の申出があり、かつ、当該申出を相当と認めるときは、当該特定事務受任者に当該除票の写し又は除票記載事項証明書を交付することができる。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"第十二条第二項から第七項までの規定は第一項の請求について、第十二条の二第二項から第五項までの規定は第二項の請求について、第十二条の三第四項から第九項までの規定は前二項の申出について、それぞれ準用する。","kind":"plain"},{"t":"この場合において、これらの規定中「住民票の写し」とあるのは「除票の写し」と、「住民票記載事項証明書」とあるのは「除票記載事項証明書」と読み替えるほか、次の表の上欄に掲げる規定中同表の中欄に掲げる字句は、それぞれ同表の下欄に掲げる字句に読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a68649dd476e"},{"num":"16","title":"第十六条","caption":"（戸籍の附票の作成）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"市町村長は、その市町村の区域内に本籍を有する者につき、その戸籍を単位として、戸籍の附票を作成しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"市町村長は、政令で定めるところにより、前項の戸籍の附票を磁気ディスクをもつて調製することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"44828eda2816"},{"num":"17","title":"第十七条","caption":"（戸籍の附票の記載事項）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"戸籍の附票には、次に掲げる事項について記載（前条第二項の規定により磁気ディスクをもつて調製する戸籍の附票にあつては、記録。以下同じ。）をする。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"戸籍の表示","kind":"plain"}]},{"n":"二","s":[{"t":"氏名","kind":"plain"}]},{"n":"二の二","s":[{"t":"氏名の振り仮名","kind":"plain"}]},{"n":"三","s":[{"t":"住所（国外に転出をする旨の第二十四条の規定による届出（次号及び第七号において「国外転出届」という。）をしたことによりいずれの市町村においても住民基本台帳に記録されていない者（以下「国外転出者」という。）にあつては、国外転出者である旨）","kind":"plain"}]},{"n":"四","s":[{"t":"住所を定めた年月日（国外転出者にあつては、その国外転出届に記載された転出の予定年月日）","kind":"plain"}]},{"n":"五","s":[{"t":"出生の年月日","kind":"plain"}]},{"n":"六","s":[{"t":"男女の別","kind":"plain"}]},{"n":"七","s":[{"t":"住民票に記載された住民票コード（国外転出者にあつては、その国外転出届をしたことにより消除された住民票に記載されていた住民票コード。第三十条の三十七及び第三十条の三十八において同じ。）","kind":"plain"}]},{"n":"八","s":[{"t":"前各号に掲げる事項のほか、政令で定める事項","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"c708ccb77d9f"},{"num":"17_2","title":"第十七条の二","caption":"（戸籍の附票の記載事項の特例等）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"戸籍の附票には、前条に規定する事項のほか、公職選挙法第三十条の六第一項の規定に基づいて在外選挙人名簿に登録された者、同条第二項の規定に基づいて在外選挙人名簿への登録の移転（同法第三十条の二第三項に規定する在外選挙人名簿への登録の移転をいう。以下この条において同じ。）がされた者及び日本国憲法の改正手続に関する法律（平成十九年法律第五十一号）第三十七条第一項の規定に基づいて在外投票人名簿に登録された者については、その旨及び当該登録又は在外選挙人名簿への登録の移転がされた市町村名を記載しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"市町村の選挙管理委員会は、公職選挙法第三十条の六第一項の規定により在外選挙人名簿に登録したとき、同条第二項の規定により在外選挙人名簿への登録の移転をしたとき、若しくは同法第三十条の十一の規定により在外選挙人名簿から抹消したとき、又は日本国憲法の改正手続に関する法律第三十七条第一項の規定により在外投票人名簿に登録したとき、若しくは同法第四十二条の規定により在外投票人名簿から抹消したときは、遅滞なく、その旨を当該登録若しくは在外選挙人名簿への登録の移転がされ、又は抹消された者の本籍地の市町村長に通知しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"dcf373527e2e"},{"num":"18","title":"第十八条","caption":"（戸籍の附票の記載等）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"戸籍の附票の記載、消除又は記載の修正（第三十条の四十一第一項において「戸籍の附票の記載等」という。）は、職権で行うものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"43c58c1da6d4"},{"num":"19","title":"第十九条","caption":"（戸籍の附票の記載の修正等のための市町村長間の通知）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"住所地の市町村長は、住民票の記載等をした場合に、本籍地において戸籍の附票の記載の修正をすべきときは、遅滞なく、当該修正をすべき事項を本籍地の市町村長に通知しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定により通知を受けた事項が戸籍の記載又は記録と合わないときは、本籍地の市町村長は、遅滞なく、その旨を住所地の市町村長に通知しなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"本籍が一の市町村から他の市町村に転属したときは、原籍地の市町村長は、遅滞なく、戸籍の附票に記載をしてある事項を新本籍地の市町村長に通知しなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"前三項の規定による通知は、総務省令（前二項の規定による通知にあつては、総務省令・法務省令。以下この項において同じ。）で定めるところにより、市町村長の使用に係る電子計算機から電気通信回線を通じて相手方である他の市町村長の使用に係る電子計算機に送信することによつて行うものとする。","kind":"main"},{"t":"ただし、総務省令で定める場合にあつては、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"9bff42761b54"},{"num":"19_2","title":"第十九条の二","caption":"（戸籍の附票の改製）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"市町村長は、必要があると認めるときは、戸籍の附票を改製することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"72f9b0656b0e"},{"num":"19_3","title":"第十九条の三","caption":"（機構への戸籍の附票の記載事項の提供）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"本籍地の市町村長は、番号利用法第二十一条の二第二項（番号利用法第二十六条において準用する場合を含む。）の規定による通知（番号利用法第十九条第八号又は第九号に規定する情報提供者又は条例事務関係情報提供者が番号利用法第九条第三項の法務大臣である場合におけるものに限る。）を受けたときは、政令で定めるところにより、当該通知に係る者の戸籍の附票に記載をされている第十七条第二号、第三号、第五号及び第六号に掲げる事項を地方公共団体情報システム機構（以下「機構」という。）に提供するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a8878cedaf64"},{"num":"20","title":"第二十条","caption":"（戸籍の附票の写しの交付）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"市町村が備える戸籍の附票に記録されている者（当該戸籍の附票から除かれた者（その者に係る全部の記載が市町村長の過誤によつてされ、かつ、当該記載が消除された者を除く。）を含む。次項において同じ。）又はその配偶者、直系尊属若しくは直系卑属は、当該市町村の市町村長に対し、これらの者に係る戸籍の附票の写し（第十六条第二項の規定により磁気ディスクをもつて戸籍の附票を調製している市町村にあつては、当該戸籍の附票に記録されている事項を記載した書類。次項及び第三項並びに第四十六条第二号において同じ。）の交付を請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"国又は地方公共団体の機関は、法令で定める事務の遂行のために必要である場合には、市町村長に対し、当該市町村が備える戸籍の附票に記録されている者に係る戸籍の附票の写しで第十七条第七号に掲げる事項の記載を省略したものの交付を請求することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"市町村長は、前二項の規定によるもののほか、当該市町村が備える戸籍の附票について、次に掲げる者から、戸籍の附票の写しで第十七条第二号から第六号までに掲げる事項のみが表示されたものが必要である旨の申出があり、かつ、当該申出を相当と認めるときは、当該申出をする者に当該戸籍の附票の写しを交付することができる。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"自己の権利を行使し、又は自己の義務を履行するために戸籍の附票の記載事項を確認する必要がある者","kind":"plain"}]},{"n":"二","s":[{"t":"国又は地方公共団体の機関に提出する必要がある者","kind":"plain"}]},{"n":"三","s":[{"t":"前二号に掲げる者のほか、戸籍の附票の記載事項を利用する正当な理由がある者","kind":"plain"}]}]},{"n":"４","s":[{"t":"市町村長は、前三項の規定によるもののほか、当該市町村が備える戸籍の附票について、第十二条の三第三項に規定する特定事務受任者から、受任している事件又は事務の依頼者が前項各号に掲げる者に該当することを理由として、同項に規定する戸籍の附票の写しが必要である旨の申出があり、かつ、当該申出を相当と認めるときは、当該特定事務受任者に当該戸籍の附票の写しを交付することができる。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"第十二条第二項から第七項までの規定は第一項の請求について、第十二条の二第二項から第五項までの規定は第二項の請求について、第十二条の三第四項から第九項までの規定は前二項の申出について、それぞれ準用する。","kind":"plain"},{"t":"この場合において、これらの規定中「総務省令」とあるのは「総務省令・法務省令」と、「住民票の写し又は住民票記載事項証明書」とあるのは「戸籍の附票の写し」と読み替えるほか、次の表の上欄に掲げる規定中同表の中欄に掲げる字句は、それぞれ同表の下欄に掲げる字句に読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"30a597897926"},{"num":"20_2","title":"第二十条の二","caption":"（戸籍の附票の脱漏等に関する都道府県知事の通報）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"都道府県知事は、その事務を管理し、又は執行するに当たつて、当該都道府県の区域内の市町村が備える戸籍の附票に脱漏、誤載、誤記又は記載漏れがあることを知つたときは、遅滞なく、その旨を当該市町村の市町村長に通報しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"dd2886142914"},{"num":"20_3","title":"第二十条の三","caption":"（戸籍の附票の脱漏等に関する委員会の通報）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"市町村の委員会は、その事務を管理し、又は執行するに当たつて、戸籍の附票に脱漏、誤載、誤記又は記載漏れがあると認めるときは、遅滞なく、その旨を当該市町村の市町村長に通報しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"73bad06a6900"},{"num":"20_4","title":"第二十条の四","caption":"（戸籍の附票の正確な記録を確保するための措置）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"市町村長は、その事務を管理し、及び執行することにより、又は第十七条の二第二項若しくは前二条の規定による通知若しくは通報によつて、戸籍の附票に脱漏、誤載、誤記又は記載漏れがあることを知つたときは、住所地の市町村長への確認その他戸籍の附票の正確な記録を確保するため必要な措置を講じなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"戸籍の附票に記録されている者は、自己又はその配偶者、直系尊属若しくは直系卑属に係る戸籍の附票に誤記又は記載漏れがあることを知つたときは、その者が記録されている戸籍の附票を備える市町村の市町村長に対してその旨を申し出ることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"1c99eb3ff48f"},{"num":"21","title":"第二十一条","caption":"（戸籍の附票の除票簿）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"市町村長は、戸籍の附票の全部を消除したとき、又は戸籍の附票を改製したときは、その消除した戸籍の附票又は改製前の戸籍の附票（以下「戸籍の附票の除票」と総称する。）をつづり、戸籍の附票の除票簿として保存しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"第十六条第二項の規定により磁気ディスクをもつて戸籍の附票を調製している市町村にあつては、磁気ディスクをもつて調製した戸籍の附票の除票を蓄積して戸籍の附票の除票簿とすることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"bc69594cfffe"},{"num":"21_2","title":"第二十一条の二","caption":"（戸籍の附票の除票の記載事項）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"戸籍の附票の除票には、当該戸籍の附票の除票に係る戸籍の附票に記載をしていた事項のほか、当該戸籍の附票を消除した旨及びその年月日又は改製した旨及びその年月日の記載（前条第二項の規定により磁気ディスクをもつて調製する戸籍の附票の除票にあつては、記録。以下同じ。）をする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"b33eff12f5fd"},{"num":"21_3","title":"第二十一条の三","caption":"（戸籍の附票の除票の写しの交付）","path":["第三章　戸籍の附票"],"paras":[{"n":"1","s":[{"t":"市町村が保存する戸籍の附票の除票に記載されている者又はその配偶者、直系尊属若しくは直系卑属は、当該市町村の市町村長に対し、これらの者に係る戸籍の附票の除票の写し（第二十一条第二項の規定により磁気ディスクをもつて戸籍の附票の除票を調製している市町村にあつては、当該戸籍の附票の除票に記録されている事項を記載した書類。次項及び第三項並びに第四十六条第二号において同じ。）の交付を請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"国又は地方公共団体の機関は、法令で定める事務の遂行のために必要である場合には、市町村長に対し、当該市町村が保存する戸籍の附票の除票の写しで第十七条第七号に掲げる事項の記載を省略したものの交付を請求することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"市町村長は、前二項の規定によるもののほか、当該市町村が保存する戸籍の附票の除票について、次に掲げる者から、当該戸籍の附票の除票の写しで第十七条第二号から第六号までに掲げる事項のみが表示されたものが必要である旨の申出があり、かつ、当該申出を相当と認めるときは、当該申出をする者に当該戸籍の附票の除票の写しを交付することができる。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"自己の権利を行使し、又は自己の義務を履行するために戸籍の附票の除票の記載事項を確認する必要がある者","kind":"plain"}]},{"n":"二","s":[{"t":"国又は地方公共団体の機関に提出する必要がある者","kind":"plain"}]},{"n":"三","s":[{"t":"前二号に掲げる者のほか、戸籍の附票の除票の記載事項を利用する正当な理由がある者","kind":"plain"}]}]},{"n":"４","s":[{"t":"市町村長は、前三項の規定によるもののほか、当該市町村が保存する戸籍の附票の除票について、第十二条の三第三項に規定する特定事務受任者から、受任している事件又は事務の依頼者が前項各号に掲げる者に該当することを理由として、同項に規定する戸籍の附票の除票の写しが必要である旨の申出があり、かつ、当該申出を相当と認めるときは、当該特定事務受任者に当該戸籍の附票の除票の写しを交付することができる。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"第十二条第二項から第七項までの規定は第一項の請求について、第十二条の二第二項から第五項までの規定は第二項の請求について、第十二条の三第四項から第九項までの規定は前二項の申出について、それぞれ準用する。","kind":"plain"},{"t":"この場合において、これらの規定中「総務省令」とあるのは「総務省令・法務省令」と、「住民票の写し又は住民票記載事項証明書」とあるのは「戸籍の附票の除票の写し」と読み替えるほか、次の表の上欄に掲げる規定中同表の中欄に掲げる字句は、それぞれ同表の下欄に掲げる字句に読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"499f8e69e216"},{"num":"21_4","title":"第二十一条の四","caption":"（住民としての地位の変更に関する届出の原則）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"住民としての地位の変更に関する届出は、全てこの章及び第四章の四に定める届出によつて行うものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"4e98f1c8f960"},{"num":"22","title":"第二十二条","caption":"（転入届）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"転入（新たに市町村の区域内に住所を定めることをいい、出生による場合を除く。以下この条及び第三十条の四十六において同じ。）をした者は、転入をした日から十四日以内に、次に掲げる事項（いずれの市町村においても住民基本台帳に記録されたことがない者にあつては、第一号から第五号まで及び第七号に掲げる事項）を市町村長に届け出なければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"氏名","kind":"plain"}]},{"n":"二","s":[{"t":"住所","kind":"plain"}]},{"n":"三","s":[{"t":"転入をした年月日","kind":"plain"}]},{"n":"四","s":[{"t":"従前の住所","kind":"plain"}]},{"n":"五","s":[{"t":"世帯主についてはその旨、世帯主でない者については世帯主の氏名及び世帯主との続柄","kind":"plain"}]},{"n":"六","s":[{"t":"転入前の住民票コード（転入をした者につき直近に住民票の記載をした市町村長が、当該住民票に直近に記載した住民票コードをいう。）","kind":"plain"}]},{"n":"七","s":[{"t":"国外から転入をした者その他政令で定める者については、前各号に掲げる事項のほか政令で定める事項","kind":"plain"}]}]},{"n":"２","s":[{"t":"前項の規定による届出をする者（同項第七号の者を除く。）は、住所の異動に関する文書で政令で定めるものを添えて、同項の届出をしなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"2b33cca58cba"},{"num":"23","title":"第二十三条","caption":"（転居届）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"転居（一の市町村の区域内において住所を変更することをいう。以下この条において同じ。）をした者は、転居をした日から十四日以内に、次に掲げる事項を市町村長に届け出なければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"氏名","kind":"plain"}]},{"n":"二","s":[{"t":"住所","kind":"plain"}]},{"n":"三","s":[{"t":"転居をした年月日","kind":"plain"}]},{"n":"四","s":[{"t":"従前の住所","kind":"plain"}]},{"n":"五","s":[{"t":"世帯主についてはその旨、世帯主でない者については世帯主の氏名及び世帯主との続柄","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"023c067c65ae"},{"num":"24","title":"第二十四条","caption":"（転出届）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"転出をする者は、あらかじめ、その氏名、転出先及び転出の予定年月日を市町村長に届け出なければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"f0ffa321a6b4"},{"num":"24_2","title":"第二十四条の二","caption":"（個人番号カードの交付を受けている者等に関する転入届の特例）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"個人番号カードの交付を受けている者が転出届（前条の規定による届出をいう。以下この条において同じ。）をした場合においては、最初の転入届（当該転出届をした日後その者が最初に行う第二十二条第一項の規定による届出をいう。以下この条において同じ。）については、第二十二条第二項の規定は、適用しない。","kind":"main"},{"t":"ただし、政令で定める場合にあつては、この限りでない。","kind":"proviso"}],"items":[]},{"n":"２","s":[{"t":"個人番号カードの交付を受けている世帯主が行う当該世帯主に関する転出届に併せて、その世帯に属する他の者（以下この項及び第二十六条において「世帯員」という。）であつて個人番号カードの交付を受けていないものが転出届をした場合においては、最初の世帯員に関する転入届（当該転出届をした日後当該世帯員が最初に行う第二十二条第一項の規定による届出であつて、当該世帯主が当該世帯主に関する最初の転入届に併せて第二十六条第一項又は第二項の規定により当該世帯員に代わつて行うものをいう。以下この条において同じ。）については、第二十二条第二項の規定は、適用しない。","kind":"main"},{"t":"ただし、政令で定める場合にあつては、この限りでない。","kind":"proviso"}],"items":[]},{"n":"３","s":[{"t":"前二項の規定による転出届を受けた市町村長は、政令で定める事項を前条の規定により届け出られた転出先に係る市町村の長（以下この条において「転入予定地市町村長」という。）に通知しなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"転入予定地市町村長は、第一項又は第二項の規定による転出届をした者が当該転入予定地市町村長に最初の転入届又は最初の世帯員に関する転入届（次項において「最初の転入届等」という。）をすることなく、前項の規定による通知があつた日から政令で定める期間が経過したときは、同項の規定により通知された事項を消去しなければならない。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"最初の転入届等を受けた市町村長（以下この条において「転入地市町村長」という。）が第三項の規定による通知を受けていない場合又は同項の規定により通知された事項を前項の規定により消去している場合には、当該転入地市町村長は、最初の転入届等を受けた旨を当該最初の転入届等に係る転出届を受けた市町村長（以下この条において「転出地市町村長」という。）に通知しなければならない。","kind":"plain"}],"items":[]},{"n":"６","s":[{"t":"転出地市町村長は、前項の規定による通知があつたときは、第三項に規定する事項を転入地市町村長に通知しなければならない。","kind":"plain"}],"items":[]},{"n":"７","s":[{"t":"第三項の規定による通知は、総務省令で定めるところにより、第一項又は第二項の規定による転出届を受けた市町村長の使用に係る電子計算機から電気通信回線を通じて相手方である転入予定地市町村長の使用に係る電子計算機に送信することによつて、前二項の規定による通知は、総務省令で定めるところにより、転入地市町村長又は転出地市町村長の使用に係る電子計算機から電気通信回線を通じて相手方である転出地市町村長又は転入地市町村長の使用に係る電子計算機に送信することによつて、それぞれ行うものとする。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"c8166c5ec2ed"},{"num":"25","title":"第二十五条","caption":"（世帯変更届）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"第二十二条第一項及び第二十三条の場合を除くほか、その属する世帯又はその世帯主に変更があつた者（政令で定める者を除く。）は、その変更があつた日から十四日以内に、その氏名、変更があつた事項及び変更があつた年月日を市町村長に届け出なければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"7c00cb8e0fe8"},{"num":"26","title":"第二十六条","caption":"（世帯主が届出を行う場合）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"世帯主は、世帯員に代わつて、この章又は第四章の四の規定による届出をすることができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"世帯員がこの章又は第四章の四の規定による届出をすることができないときは、世帯主が世帯員に代わつて、その届出をしなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"b56780d325f1"},{"num":"27","title":"第二十七条","caption":"（届出の方式等）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"この章又は第四章の四の規定による届出は、政令で定めるところにより、書面でしなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"市町村長は、この章又は第四章の四の規定による届出がされる場合において、現に届出の任に当たつている者に対し、総務省令で定めるところにより、当該届出の任に当たつている者が本人であるかどうかの確認をするため、当該届出の任に当たつている者を特定するために必要な氏名その他の総務省令で定める事項を示す書類の提示若しくは提出又はこれらの事項についての説明を求めるものとする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前項の場合において、市町村長は、現に届出の任に当たつている者が、届出をする者の代理人であるときその他届出をする者と異なる者であるとき（現に届出の任に当たつている者が届出をする者と同一の世帯に属する者であるときを除く。）は、当該届出の任に当たつている者に対し、総務省令で定めるところにより、届出をする者の依頼により又は法令の規定により当該届出の任に当たるものであることを明らかにするために必要な事項を示す書類の提示若しくは提出又は当該事項についての説明を求めるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"7a24bc34bee2"},{"num":"28","title":"第二十八条","caption":"（国民健康保険の被保険者である者に係る届出の特例）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"この章又は第四章の四の規定による届出をすべき者が国民健康保険の被保険者であるときは、その者は、当該届出に係る書面に、その資格を証する事項で政令で定めるものを付記するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"18ff601ab697"},{"num":"28_2","title":"第二十八条の二","caption":"（後期高齢者医療の被保険者である者に係る届出の特例）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"この章又は第四章の四の規定による届出をすべき者が後期高齢者医療の被保険者であるときは、その者は、当該届出に係る書面に、その資格を証する事項で政令で定めるものを付記するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"501151158267"},{"num":"28_3","title":"第二十八条の三","caption":"（介護保険の被保険者である者に係る届出の特例）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"この章又は第四章の四の規定による届出をすべき者が介護保険の被保険者であるときは、その者は、当該届出に係る書面に、その資格を証する事項で政令で定めるものを付記するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"490b031c2691"},{"num":"29","title":"第二十九条","caption":"（国民年金の被保険者である者に係る届出の特例）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"この章又は第四章の四の規定による届出をすべき者が国民年金の被保険者であるときは、その者は、当該届出に係る書面に、その資格を証する事項その他必要な事項で政令で定めるものを付記するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"df1dda046b20"},{"num":"29_2","title":"第二十九条の二","caption":"（児童手当の支給を受けている者に係る届出の特例）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"この章又は第四章の四の規定による届出をすべき者が児童手当の支給を受けている者であるときは、その者は、当該届出に係る書面に、その受給資格に関する事項で政令で定めるものを付記するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"75846314f36f"},{"num":"30","title":"第三十条","caption":"（米穀の配給を受ける者に係る届出の特例）","path":["第四章　届出"],"paras":[{"n":"1","s":[{"t":"この章又は第四章の四の規定による届出をすべき者が米穀の配給を受ける者であるときは、その者は、当該届出に係る書面に、米穀の配給に関する事項で政令で定めるものを付記するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e8ada148711f"},{"num":"30_2","title":"第三十条の二","caption":"（住民票コードの指定）","path":["第四章の二　本人確認情報の処理及び利用等","第一節　住民票コード"],"paras":[{"n":"1","s":[{"t":"機構は、総務省令で定めるところにより、市町村長ごとに、当該市町村長が住民票に記載することのできる住民票コードを指定し、これを当該市町村長に通知するものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"機構は、前項の規定による住民票コードの指定を行う場合には、市町村長に対して指定する住民票コードが当該指定前に指定した住民票コードと重複しないようにしなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a8dfd7ea417f"},{"num":"30_3","title":"第三十条の三","caption":"（住民票コードの記載等）","path":["第四章の二　本人確認情報の処理及び利用等","第一節　住民票コード"],"paras":[{"n":"1","s":[{"t":"市町村長は、次項に規定する場合を除き、住民票の記載をする場合には、当該記載に係る者につき直近に住民票の記載をした市町村長が当該住民票に直近に記載した住民票コードを記載するものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"市町村長は、新たにその市町村の住民基本台帳に記録されるべき者につき住民票の記載をする場合において、その者がいずれの市町村においても住民基本台帳に記録されたことがない者であるときは、その者に係る住民票に前条第一項の規定により機構から指定された住民票コードのうちから選択するいずれか一の住民票コードを記載するものとする。","kind":"plain"},{"t":"この場合において、市町村長は、当該記載に係る者以外の者に係る住民票に記載した住民票コードと異なる住民票コードを選択して記載するものとする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"市町村長は、前項の規定により住民票コードを記載したときは、速やかに、当該記載に係る者に対し、その旨及び当該住民票コードを書面により通知しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"904463276517"},{"num":"30_4","title":"第三十条の四","caption":"（住民票コードの記載の変更請求）","path":["第四章の二　本人確認情報の処理及び利用等","第一節　住民票コード"],"paras":[{"n":"1","s":[{"t":"住民基本台帳に記録されている者は、その者が記録されている住民基本台帳を備える市町村の市町村長に対し、その者に係る住民票に記載されている住民票コードの記載の変更を請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定による住民票コードの記載の変更の請求（以下この条において「変更請求」という。）をしようとする者は、政令で定めるところにより、その旨その他総務省令で定める事項を記載した変更請求書を、その者が記録されている住民基本台帳を備える市町村の市町村長に提出しなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"市町村長は、前項の変更請求書の提出があつた場合には、当該変更請求をした者に係る住民票に従前記載されていた住民票コードに代えて、第三十条の二第一項の規定により機構から指定された住民票コードのうちから選択するいずれか一の新たな住民票コードをその者に係る住民票に記載するものとする。","kind":"plain"},{"t":"この場合において、市町村長は、当該記載に係る者以外の者に係る住民票に記載した住民票コードと異なる住民票コードを選択して記載するものとする。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"市町村長は、前項の規定により新たな住民票コードを記載したときは、速やかに、当該変更請求をした者に対し、住民票コードの記載の変更をした旨及び新たに記載された住民票コードを書面により通知しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"bf80bae80977"},{"num":"30_5","title":"第三十条の五","caption":"（政令への委任）","path":["第四章の二　本人確認情報の処理及び利用等","第一節　住民票コード"],"paras":[{"n":"1","s":[{"t":"前三条に定めるもののほか、住民票コードの記載に関し必要な事項は、政令で定める。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c8aff79a949c"},{"num":"30_6","title":"第三十条の六","caption":"（市町村長から都道府県知事への本人確認情報の通知等）","path":["第四章の二　本人確認情報の処理及び利用等","第二節　本人確認情報の通知及び保存等"],"paras":[{"n":"1","s":[{"t":"市町村長は、住民票の記載、消除又は第七条第一号から第三号まで、第七号、第八号の二及び第十三号に掲げる事項（同条第七号に掲げる事項については、住所とする。以下この項において同じ。）の全部若しくは一部についての記載の修正を行つた場合には、当該住民票の記載等に係る本人確認情報（住民票に記載されている同条第一号から第三号まで、第七号、第八号の二及び第十三号に掲げる事項（住民票の消除を行つた場合には、当該住民票に記載されていたこれらの事項）並びに住民票の記載等に関する事項で政令で定めるものをいう。以下同じ。）を都道府県知事に通知するものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定による通知は、総務省令で定めるところにより、市町村長の使用に係る電子計算機から電気通信回線を通じて都道府県知事の使用に係る電子計算機に送信することによつて行うものとする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"第一項の規定による通知を受けた都道府県知事は、総務省令で定めるところにより、当該通知に係る本人確認情報を磁気ディスクに記録し、これを当該通知の日から政令で定める期間保存しなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"都道府県知事は、前項の規定により都道府県知事が保存する本人確認情報であつて同項の規定による保存期間が経過していないもの（以下「都道府県知事保存本人確認情報」という。）の全部又は一部が滅失したときは、当該都道府県知事保存本人確認情報の回復に必要な措置を講じなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ff31e329a411"},{"num":"30_7","title":"第三十条の七","caption":"（都道府県知事から機構への本人確認情報の通知等）","path":["第四章の二　本人確認情報の処理及び利用等","第二節　本人確認情報の通知及び保存等"],"paras":[{"n":"1","s":[{"t":"都道府県知事は、前条第一項の規定による通知に係る本人確認情報を、機構に通知するものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定による通知は、総務省令で定めるところにより、都道府県知事の使用に係る電子計算機から電気通信回線を通じて機構の使用に係る電子計算機に送信することによつて行うものとする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"第一項の規定による通知を受けた機構は、総務省令で定めるところにより、当該通知に係る本人確認情報を磁気ディスクに記録し、これを当該通知の日から政令で定める期間保存しなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"機構は、前項の規定により機構が保存する本人確認情報であつて同項の規定による保存期間が経過していないもの（以下「機構保存本人確認情報」という。）の全部又は一部が滅失したときは、当該機構保存本人確認情報の回復に必要な措置を講じなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"47722b4e186b"},{"num":"30_8","title":"第三十条の八","caption":"（本人確認情報の誤りに関する機構の通報）","path":["第四章の二　本人確認情報の処理及び利用等","第二節　本人確認情報の通知及び保存等"],"paras":[{"n":"1","s":[{"t":"機構は、その事務を管理し、又は執行するに当たつて、都道府県知事保存本人確認情報に誤りがあることを知つたときは、遅滞なく、その旨を当該都道府県知事保存本人確認情報を保存する都道府県知事に通報するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"88decc99f41a"},{"num":"30_9","title":"第三十条の九","caption":"（国の機関等への本人確認情報の提供）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、別表第一の上欄に掲げる国の機関又は法人から同表の下欄に掲げる事務の処理に関し求めがあつたときは、政令で定めるところにより、機構保存本人確認情報のうち住民票コード以外のものを提供するものとする。","kind":"main"},{"t":"ただし、個人番号については、当該同表の上欄に掲げる国の機関又は法人が番号利用法第九条第一項の規定により個人番号を利用することができる場合に限り、提供するものとする。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"4e490df0d504"},{"num":"30_9_2","title":"第三十条の九の二","caption":"（デジタル庁への住民票コードの提供）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、デジタル庁から番号利用法第二十一条第二項又は第二十一条の二第一項（これらの規定を番号利用法第二十六条において準用する場合を含む。）の規定による事務の処理に関し求めがあつたときは、政令で定めるところにより、当該求めに係る者の住民票に記載された住民票コードを提供するものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"機構は、前項又は第三十条の四十四の二の規定により提供した住民票コードが記載された住民票について当該住民票コードの記載の修正が行われたことを知つたときは、デジタル庁に対し、修正前及び修正後の住民票コードを提供するものとする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前二項に規定する場合において、機構は、機構保存本人確認情報を利用することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"93f0e3fa102d"},{"num":"30_10","title":"第三十条の十","caption":"（通知都道府県の区域内の市町村の執行機関への本人確認情報の提供）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、次の各号のいずれかに該当する場合には、政令で定めるところにより、本人確認情報を第三十条の七第一項の規定により通知した都道府県知事が統括する都道府県（以下「通知都道府県」という。）の区域内の市町村の市町村長その他の執行機関に対し、機構保存本人確認情報（第一号から第三号までに掲げる場合にあつては、住民票コードを除く。）を提供するものとする。","kind":"main"},{"t":"ただし、第一号に掲げる場合にあつては、個人番号については、当該市町村長その他の市町村の執行機関が番号利用法第九条第一項の規定により個人番号を利用することができる場合に限り、提供するものとする。","kind":"proviso"}],"items":[{"n":"一","s":[{"t":"通知都道府県の区域内の市町村の市町村長その他の執行機関であつて別表第二の上欄に掲げるものから同表の下欄に掲げる事務の処理に関し求めがあつたとき。","kind":"plain"}]},{"n":"二","s":[{"t":"通知都道府県の区域内の市町村の市町村長その他の執行機関から番号利用法第九条第二項の規定に基づき条例で定める事務の処理に関し求めがあつたとき。","kind":"plain"}]},{"n":"三","s":[{"t":"通知都道府県の区域内の市町村の市町村長から番号利用法第十七条第一項の規定に基づき国外転出者に係る個人番号カードの交付に関する事務の処理に関し求めがあつたとき。","kind":"plain"}]},{"n":"四","s":[{"t":"通知都道府県の区域内の市町村の市町村長から住民基本台帳に関する事務の処理に関し求めがあつたとき。","kind":"plain"}]}]},{"n":"２","s":[{"t":"前項（第四号に係る部分に限る。）の規定による通知都道府県の区域内の市町村の市町村長への機構保存本人確認情報の提供は、総務省令で定めるところにより、機構の使用に係る電子計算機から電気通信回線を通じて当該市町村長の使用に係る電子計算機に送信することによつて行うものとする。","kind":"main"},{"t":"ただし、特別の求めがあつたときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"f44d2f2785ea"},{"num":"30_11","title":"第三十条の十一","caption":"（通知都道府県以外の都道府県の執行機関への本人確認情報の提供）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、次の各号のいずれかに該当する場合には、政令で定めるところにより、通知都道府県以外の都道府県の都道府県知事その他の執行機関に対し、機構保存本人確認情報（第一号及び第二号に掲げる場合にあつては、住民票コードを除く。）を提供するものとする。","kind":"main"},{"t":"ただし、第一号に掲げる場合にあつては、個人番号については、当該都道府県知事その他の都道府県の執行機関が番号利用法第九条第一項の規定により個人番号を利用することができる場合に限り、提供するものとする。","kind":"proviso"}],"items":[{"n":"一","s":[{"t":"通知都道府県以外の都道府県の都道府県知事その他の執行機関であつて別表第三の上欄に掲げるものから同表の下欄に掲げる事務の処理に関し求めがあつたとき。","kind":"plain"}]},{"n":"二","s":[{"t":"通知都道府県以外の都道府県の都道府県知事その他の執行機関から番号利用法第九条第二項の規定に基づき条例で定める事務の処理に関し求めがあつたとき。","kind":"plain"}]},{"n":"三","s":[{"t":"通知都道府県以外の都道府県の都道府県知事から第三十条の二十二第二項の規定による事務の処理に関し求めがあつたとき。","kind":"plain"}]}]},{"n":"２","s":[{"t":"前項（第三号に係る部分に限る。）の規定による通知都道府県以外の都道府県の都道府県知事への機構保存本人確認情報の提供は、総務省令で定めるところにより、機構の使用に係る電子計算機から電気通信回線を通じて当該都道府県知事の使用に係る電子計算機に送信することによつて行うものとする。","kind":"main"},{"t":"ただし、特別の求めがあつたときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"0afdbb9c2dde"},{"num":"30_12","title":"第三十条の十二","caption":"（通知都道府県以外の都道府県の区域内の市町村の執行機関への本人確認情報の提供）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、次の各号のいずれかに該当する場合には、政令で定めるところにより、通知都道府県以外の都道府県の区域内の市町村の市町村長その他の執行機関に対し、機構保存本人確認情報（第一号から第三号までに掲げる場合にあつては、住民票コードを除く。）を提供するものとする。","kind":"main"},{"t":"ただし、第一号に掲げる場合にあつては、個人番号については、当該市町村長その他の市町村の執行機関が番号利用法第九条第一項の規定により個人番号を利用することができる場合に限り、提供するものとする。","kind":"proviso"}],"items":[{"n":"一","s":[{"t":"通知都道府県以外の都道府県の区域内の市町村の市町村長その他の執行機関であつて別表第四の上欄に掲げるものから通知都道府県以外の都道府県の都道府県知事を経て同表の下欄に掲げる事務の処理に関し求めがあつたとき。","kind":"plain"}]},{"n":"二","s":[{"t":"通知都道府県以外の都道府県の区域内の市町村の市町村長その他の執行機関から番号利用法第九条第二項の規定に基づき条例で定める事務の処理に関し求めがあつたとき。","kind":"plain"}]},{"n":"三","s":[{"t":"通知都道府県以外の都道府県の区域内の市町村の市町村長から番号利用法第十七条第一項の規定に基づき国外転出者に係る個人番号カードの交付に関する事務の処理に関し求めがあつたとき。","kind":"plain"}]},{"n":"四","s":[{"t":"通知都道府県以外の都道府県の区域内の市町村の市町村長から通知都道府県以外の都道府県の都道府県知事を経て住民基本台帳に関する事務の処理に関し求めがあつたとき。","kind":"plain"}]}]},{"n":"２","s":[{"t":"前項（第四号に係る部分に限る。）の規定による通知都道府県以外の都道府県の区域内の市町村の市町村長への機構保存本人確認情報の提供は、総務省令で定めるところにより、機構の使用に係る電子計算機から電気通信回線を通じて当該市町村長の使用に係る電子計算機に送信することによつて行うものとする。","kind":"main"},{"t":"ただし、特別の求めがあつたときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"4fc6d9dedd45"},{"num":"30_13","title":"第三十条の十三","caption":"（都道府県の条例による本人確認情報の提供）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"都道府県知事は、当該都道府県の区域内の市町村の市町村長その他の執行機関であつて条例で定めるものから条例で定める事務の処理に関し求めがあつたときは、条例で定めるところにより、当該市町村長その他の市町村の執行機関に対し、都道府県知事保存本人確認情報（住民票コード及び個人番号を除く。以下この条において同じ。）を提供するものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"都道府県知事は、他の都道府県の都道府県知事その他の執行機関であつて条例で定めるものから条例で定める事務の処理に関し求めがあつたときは、条例で定めるところにより、当該都道府県知事その他の都道府県の執行機関に対し、都道府県知事保存本人確認情報を提供するものとする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"都道府県知事は、他の都道府県の区域内の市町村の市町村長その他の執行機関であつて条例で定めるものから他の都道府県の都道府県知事を経て条例で定める事務の処理に関し求めがあつたときは、条例で定めるところにより、当該市町村長その他の市町村の執行機関に対し、都道府県知事保存本人確認情報を提供するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"cef6048a23f8"},{"num":"30_14","title":"第三十条の十四","caption":"（市町村の条例による本人確認情報の提供）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"市町村長は、他の市町村の市町村長その他の執行機関であつて条例で定めるものから条例で定める事務の処理に関し求めがあつたときは、条例で定めるところにより、当該市町村長その他の市町村の執行機関に対し、本人確認情報（住民票コード及び個人番号を除く。）を提供するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"cc5899f87abe"},{"num":"30_15","title":"第三十条の十五","caption":"（本人確認情報の利用）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"都道府県知事は、次の各号のいずれかに該当する場合には、都道府県知事保存本人確認情報（住民票コードを除く。次項並びに次条第二項及び第三項において同じ。）を利用することができる。","kind":"main"},{"t":"ただし、個人番号については、当該都道府県知事が番号利用法第九条第一項又は第二項の規定により個人番号を利用することができる場合に限り、利用することができるものとする。","kind":"proviso"}],"items":[{"n":"一","s":[{"t":"別表第五に掲げる事務を遂行するとき。","kind":"plain"}]},{"n":"二","s":[{"t":"条例で定める事務を遂行するとき。","kind":"plain"}]},{"n":"三","s":[{"t":"本人確認情報の利用につき当該本人確認情報に係る本人が同意した事務を遂行するとき。","kind":"plain"}]},{"n":"四","s":[{"t":"統計資料の作成を行うとき。","kind":"plain"}]}]},{"n":"２","s":[{"t":"都道府県知事は、次の各号のいずれかに該当する場合には、第一号に掲げる場合にあつては政令で定めるところにより、第二号に掲げる場合にあつては条例で定めるところにより、都道府県知事以外の当該都道府県の執行機関に対し、都道府県知事保存本人確認情報を提供するものとする。","kind":"main"},{"t":"ただし、個人番号については、当該都道府県の執行機関が番号利用法第九条第一項又は第二項の規定により個人番号を利用することができる場合に限り、提供するものとする。","kind":"proviso"}],"items":[{"n":"一","s":[{"t":"都道府県知事以外の当該都道府県の執行機関であつて別表第六の上欄に掲げるものから同表の下欄に掲げる事務の処理に関し求めがあつたとき。","kind":"plain"}]},{"n":"二","s":[{"t":"都道府県知事以外の当該都道府県の執行機関であつて条例で定めるものから条例で定める事務の処理に関し求めがあつたとき。","kind":"plain"}]}]},{"n":"３","s":[{"t":"機構は、機構保存本人確認情報を、第三十条の四十二第四項又は第三十条の四十四の十一第三項の規定による事務に利用することができる。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"機構は、機構保存本人確認情報（個人番号を除く。）を、電子署名等に係る地方公共団体情報システム機構の認証業務に関する法律（平成十四年法律第百五十三号）第八条、第十一条、第十二条、第十三条、第十五条第二項、第十六条の七、第十六条の十、第十六条の十一、第十六条の十四第二項、第十八条第四項及び第五項、第二十七条、第三十条、第三十一条、第三十四条第二項、第三十五条の七、第三十五条の十、第三十五条の十四第二項並びに第三十七条第三項の規定による事務に利用することができる。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"機構は、機構保存本人確認情報を、番号利用法第八条第二項及び第十六条の二の規定による事務その他の番号利用法第三十八条の二第一項に規定する機構処理事務のうち総務省令で定めるものに利用することができる。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"11b27f9e5afb"},{"num":"30_15_2","title":"第三十条の十五の二","caption":"（準法定事務処理者への本人確認情報の提供等）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、国の機関若しくは別表第一の上欄に掲げる法人、市町村長その他の市町村の執行機関又は通知都道府県以外の都道府県の都道府県知事その他の執行機関であつて、準法定事務（別表第一から別表第四までの各項の下欄、別表第五各号及び別表第六の各項の下欄に掲げる事務（以下この項において「別表事務」という。）に準ずる事務（個別の法律の規定に基づく事務を除き、番号利用法第九条第一項の規定により個人番号を利用することができる事務であつて当該事務の性質が当該別表事務と同一であることその他政令で定める基準に適合するものに限る。）をいう。以下同じ。）のうち総務省令で定めるものを処理する者として総務省令で定めるもの（以下「準法定事務処理者」という。）から当該準法定事務の処理に関し求めがあつたときは、政令で定めるところにより、機構保存本人確認情報のうち住民票コード以外のものを提供するものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"都道府県知事は、準法定事務のうち総務省令で定めるものを遂行するときは、都道府県知事保存本人確認情報を利用することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"都道府県知事は、都道府県知事以外の当該都道府県の執行機関であつて、準法定事務のうち総務省令で定めるものを処理する者として総務省令で定めるものから当該準法定事務の処理に関し求めがあつたときは、政令で定めるところにより、都道府県知事保存本人確認情報を提供するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"08029631fbdc"},{"num":"30_16","title":"第三十条の十六","caption":"（報告書の公表）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、毎年少なくとも一回、第三十条の九、第三十条の九の二及び前条第一項（準法定事務処理者（国の機関又は別表第一の上欄に掲げる法人に限る。第三十条の二十三、第三十条の二十八第一項及び第三十条の三十第二項において同じ。）への機構保存本人確認情報の提供に係る部分に限る。）の規定による機構保存本人確認情報及び住民票コードの提供の状況について、総務省令で定めるところにより、報告書を作成し、これを公表しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"7c5dbf850f08"},{"num":"30_17","title":"第三十条の十七","caption":"（本人確認情報管理規程）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、この章及び第三十七条第二項の規定により機構が処理することとされている事務（以下「本人確認情報処理事務」という。）の実施に関し総務省令で定める事項について本人確認情報管理規程を定め、総務大臣の認可を受けなければならない。","kind":"plain"},{"t":"これを変更しようとするときも、同様とする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"総務大臣は、前項の規定により認可をした本人確認情報管理規程が本人確認情報処理事務の適正かつ確実な実施上不適当となつたと認めるときは、機構に対し、これを変更すべきことを命ずることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"525c52c9b866"},{"num":"30_18","title":"第三十条の十八","caption":"（帳簿の備付け）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、総務省令で定めるところにより、本人確認情報処理事務に関する事項で総務省令で定めるものを記載した帳簿を備え、保存しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"222586286be7"},{"num":"30_19","title":"第三十条の十九","caption":"（監督命令等）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"総務大臣は、本人確認情報処理事務の適正な実施を確保するため必要があると認めるときは、機構に対し、本人確認情報処理事務の実施に関し監督上必要な命令をすることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"f9e0d7dad1cf"},{"num":"30_20","title":"第三十条の二十","caption":"（報告及び立入検査）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"総務大臣は、本人確認情報処理事務の適正な実施を確保するため必要があると認めるときは、機構に対し、本人確認情報処理事務の実施の状況に関し必要な報告を求め、又はその職員に、機構の事務所に立ち入り、本人確認情報処理事務の実施の状況若しくは帳簿、書類その他の物件を検査させることができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定により立入検査をする職員は、その身分を示す証明書を携帯し、関係人の請求があつたときは、これを提示しなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"第一項の規定による立入検査の権限は、犯罪捜査のために認められたものと解釈してはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"2d0cc4a5cd69"},{"num":"30_21","title":"第三十条の二十一","caption":"（都道府県知事に対する技術的な助言等）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、都道府県知事に対し、第三十条の六第一項の規定による通知に係る本人確認情報の電子計算機処理（電子計算機を使用して行われる情報の入力、蓄積、編集、加工、修正、更新、検索、消去、出力又はこれらに類する処理をいう。以下同じ。）に関し必要な技術的な助言及び情報の提供を行うものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"2e76992e3af7"},{"num":"30_22","title":"第三十条の二十二","caption":"（市町村間の連絡調整等）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"都道府県知事は、第三十条の六第二項の規定による電気通信回線を通じた本人確認情報の送信その他この章に規定する市町村の事務の処理に関し、当該都道府県の区域内の市町村相互間における必要な連絡調整を行うものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"都道府県知事は、当該都道府県の区域内の市町村の市町村長に対し、住民基本台帳に住民に関する正確な記録が行われるよう、必要な協力をするものとする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"機構は、都道府県知事に対し、当該都道府県の区域内の市町村の住民基本台帳に住民に関する正確な記録が行われるよう、必要な協力をしなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"623adbd50810"},{"num":"30_23","title":"第三十条の二十三","caption":"（本人確認情報等の提供に関する手数料）","path":["第四章の二　本人確認情報の処理及び利用等","第三節　本人確認情報の提供及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、第三十条の九、第三十条の九の二第一項又は第三十条の十五の二第一項に規定する求めを行う別表第一の上欄に掲げる国の機関若しくは法人若しくは準法定事務処理者又はデジタル庁から、総務大臣の認可を受けて定める額の手数料を徴収することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"7d16f74114c6"},{"num":"30_24","title":"第三十条の二十四","caption":"（本人確認情報の安全確保）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"都道府県知事は、第三十条の六第一項の規定による通知に係る本人確認情報の電子計算機処理等（電子計算機処理又は情報の入力のための準備作業若しくは磁気ディスクの保管をいう。以下同じ。）を行うに当たつては、当該本人確認情報の漏えい、滅失及び毀損の防止その他の当該本人確認情報の適切な管理のために必要な措置を講じなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"機構は、第三十条の七第一項の規定による通知に係る本人確認情報の電子計算機処理等を行うに当たつては、当該本人確認情報の漏えい、滅失及び毀損の防止その他の当該本人確認情報の適切な管理のために必要な措置を講じなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前二項の規定は、都道府県知事又は機構から第三十条の六第一項又は第三十条の七第一項の規定による通知に係る本人確認情報の電子計算機処理等の委託（二以上の段階にわたる委託を含む。）を受けた者が受託した業務を行う場合について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a215d12f336a"},{"num":"30_25","title":"第三十条の二十五","caption":"（本人確認情報の提供及び利用の制限）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"都道府県知事は、第三十条の十三、第三十条の十五第一項若しくは第二項、第三十条の十五の二第二項若しくは第三項又は第三十七条第二項の規定により都道府県知事保存本人確認情報を提供し、又は利用する場合を除き、第三十条の六第一項の規定による通知に係る本人確認情報を提供し、又は利用してはならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"機構は、第三十条の九から第三十条の十二まで、第三十条の十五第三項から第五項まで、第三十条の十五の二第一項又は第三十七条第二項の規定により機構保存本人確認情報又は住民票コードを提供し、又は利用する場合を除き、第三十条の七第一項の規定による通知に係る本人確認情報を提供し、又は利用してはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"549c9b35013a"},{"num":"30_26","title":"第三十条の二十六","caption":"（本人確認情報の電子計算機処理等に従事する市町村若しくは都道府県又は機構の職員等の秘密保持義務）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"本人確認情報の電子計算機処理等に関する事務に従事する市町村の職員若しくは職員であつた者又は第三十条の六第一項の規定による通知に係る本人確認情報の電子計算機処理等に関する事務に従事する都道府県の職員若しくは職員であつた者は、その事務に関して知り得た本人確認情報に関する秘密又は本人確認情報の電子計算機処理等に関する秘密を漏らしてはならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"市町村長若しくは都道府県知事から本人確認情報若しくは第三十条の六第一項の規定による通知に係る本人確認情報の電子計算機処理等の委託（二以上の段階にわたる委託を含む。）を受けた者若しくはその役員若しくは職員又はこれらの者であつた者は、その委託された業務に関して知り得た本人確認情報に関する秘密又は本人確認情報の電子計算機処理等に関する秘密を漏らしてはならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"機構の役員若しくは職員（地方公共団体情報システム機構法（平成二十五年法律第二十九号）第二十五条第一項に規定する本人確認情報保護委員会の委員を含む。）又はこれらの職にあつた者は、本人確認情報処理事務に関して知り得た秘密を漏らしてはならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"機構から第三十条の七第一項の規定による通知に係る本人確認情報の電子計算機処理等の委託（二以上の段階にわたる委託を含む。）を受けた者若しくはその役員若しくは職員又はこれらの者であつた者は、その委託された業務に関して知り得た本人確認情報に関する秘密又は本人確認情報の電子計算機処理等に関する秘密を漏らしてはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ca9ddaa82811"},{"num":"30_27","title":"第三十条の二十七","caption":"（本人確認情報に係る住民に関する記録の保護）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"都道府県知事の委託（二以上の段階にわたる委託を含む。）を受けて行う第三十条の六第一項の規定による通知に係る本人確認情報の電子計算機処理等に関する事務に従事している者又は従事していた者は、その事務に関して知り得た事項をみだりに他人に知らせ、又は不当な目的に使用してはならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"機構の委託（二以上の段階にわたる委託を含む。）を受けて行う第三十条の七第一項の規定による通知に係る本人確認情報の電子計算機処理等に関する事務に従事している者又は従事していた者は、その事務に関して知り得た事項をみだりに他人に知らせ、又は不当な目的に使用してはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"0dd295d47a95"},{"num":"30_28","title":"第三十条の二十八","caption":"（受領者等による本人確認情報等の安全確保）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"第三十条の九、第三十条の十から第三十条の十四まで、第三十条の十五第二項若しくは第三十条の十五の二第一項若しくは第三項の規定により本人確認情報の提供を受けた市町村長その他の市町村の執行機関、都道府県知事その他の都道府県の執行機関若しくは別表第一の上欄に掲げる国の機関若しくは法人若しくは準法定事務処理者又は第三十条の九の二の規定により住民票コードの提供を受けたデジタル庁（以下「受領者」という。）がこれらの規定により提供を受けた本人確認情報又は住民票コード（以下「受領した本人確認情報等」という。）の電子計算機処理等を行うに当たつては、受領者は、受領した本人確認情報等の漏えい、滅失及び毀損の防止その他の当該受領した本人確認情報等の適切な管理のために必要な措置を講じなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、受領者から受領した本人確認情報等の電子計算機処理等の委託（二以上の段階にわたる委託を含む。）を受けた者が受託した業務を行う場合について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"9c1b65ed0923"},{"num":"30_29","title":"第三十条の二十九","caption":"（受領者の本人確認情報等の利用及び提供の制限）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"受領者は、その者が処理する事務であつてこの法律の定めるところにより当該事務の処理に関し本人確認情報等（本人確認情報又は住民票コードをいう。次条第二項及び第三項において同じ。）の提供を求めることができることとされているものの遂行に必要な範囲内で、受領した本人確認情報等を利用し、又は提供するものとし、当該事務の処理以外の目的のために受領した本人確認情報等の全部又は一部を利用し、又は提供してはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"5bb092c1ffa9"},{"num":"30_30","title":"第三十条の三十","caption":"（本人確認情報等の電子計算機処理等に従事する受領者の職員等の秘密保持義務）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"第三十条の十から第三十条の十四まで、第三十条の十五第二項又は第三十条の十五の二第一項若しくは第三項の規定により市町村長その他の市町村の執行機関又は都道府県知事その他の都道府県の執行機関が提供を受けた本人確認情報の電子計算機処理等に関する事務に従事する市町村又は都道府県の職員又は職員であつた者は、その事務に関して知り得た本人確認情報に関する秘密又は本人確認情報の電子計算機処理等に関する秘密を漏らしてはならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"第三十条の九、第三十条の九の二又は第三十条の十五の二第一項の規定により別表第一の上欄に掲げる国の機関若しくは法人若しくは準法定事務処理者又はデジタル庁が提供を受けた本人確認情報等の電子計算機処理等に関する事務に従事する同欄に掲げる国の機関の職員若しくは職員であつた者、同欄に掲げる法人の役員若しくは職員若しくはこれらの職にあつた者、準法定事務処理者の役員若しくは職員若しくはこれらの職にあつた者又はデジタル庁の職員若しくは職員であつた者は、その事務に関して知り得た本人確認情報等に関する秘密又は本人確認情報等の電子計算機処理等に関する秘密を漏らしてはならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"受領者から受領した本人確認情報等の電子計算機処理等の委託（二以上の段階にわたる委託を含む。）を受けた者若しくはその役員若しくは職員又はこれらの者であつた者は、その委託された業務に関して知り得た本人確認情報等に関する秘密又は本人確認情報等の電子計算機処理等に関する秘密を漏らしてはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"729cb08195c8"},{"num":"30_31","title":"第三十条の三十一","caption":"（受領した本人確認情報等に係る住民に関する記録の保護）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"受領者の委託（二以上の段階にわたる委託を含む。）を受けて行う受領した本人確認情報等の電子計算機処理等に関する事務に従事している者又は従事していた者は、その事務に関して知り得た事項をみだりに他人に知らせ、又は不当な目的に使用してはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"00d9c640b0e9"},{"num":"30_32","title":"第三十条の三十二","caption":"（自己の本人確認情報の開示）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"何人も、都道府県知事又は機構に対し、第三十条の六第三項又は第三十条の七第三項の規定により磁気ディスクに記録されている自己に係る本人確認情報について、書面により、その開示（自己に係る本人確認情報が存在しないときにその旨を知らせることを含む。以下同じ。）を請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"都道府県知事又は機構は、前項の開示の請求（以下この項及び次条第一項において「開示請求」という。）があつたときは、開示請求をした者（以下この項及び次条第二項において「開示請求者」という。）に対し、書面により、当該開示請求に係る本人確認情報について開示をしなければならない。","kind":"main"},{"t":"ただし、開示請求者の同意があるときは、書面以外の方法により開示をすることができる。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"d89029cab9f7"},{"num":"30_33","title":"第三十条の三十三","caption":"（開示の期限）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"前条第二項の規定による開示は、開示請求を受理した日から起算して三十日以内にしなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"都道府県知事又は機構は、事務処理上の困難その他正当な理由により前項に規定する期間内に開示をすることができないときは、同項に規定する期間内に、開示請求者に対し、同項の期間内に開示をすることができない理由及び開示の期限を書面により通知しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"bdb5850b1764"},{"num":"30_34","title":"第三十条の三十四","caption":"（開示の手数料）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"第三十条の三十二第一項の規定により機構に対し自己に係る本人確認情報の開示を請求する者は、機構が総務大臣の認可を受けて定める額の手数料を納めなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"dfa0a8a58aaf"},{"num":"30_35","title":"第三十条の三十五","caption":"（自己の本人確認情報の訂正）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"都道府県知事又は機構は、第三十条の三十二第二項の規定により開示を受けた者から、書面により、開示に係る本人確認情報についてその内容の全部又は一部の訂正、追加又は削除の申出があつたときは、遅滞なく調査を行い、その結果を当該申出をした者に対し、書面で通知するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"6ebd03d9bf1b"},{"num":"30_36","title":"第三十条の三十六","caption":"（苦情処理）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"都道府県知事又は機構は、この法律の規定（第三章及び次章を除く。）により都道府県が処理する事務又は本人確認情報処理事務の実施に関する苦情の適切かつ迅速な処理に努めなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"81e1bf0d86e1"},{"num":"30_37","title":"第三十条の三十七","caption":"（住民票コードの告知要求制限）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"市町村長は、この法律の規定による事務の遂行のため必要がある場合を除き、何人に対しても、当該市町村の住民以外の者に係る住民票に記載された住民票コードを告知することを求めてはならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"都道府県知事は、この法律の規定による事務の遂行のため必要がある場合を除き、何人に対しても、その者又はその者以外の者に係る住民票に記載された住民票コードを告知することを求めてはならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"機構は、この法律の規定により機構が処理することとされている事務の遂行のため必要がある場合を除き、何人に対しても、その者又はその者以外の者に係る住民票に記載された住民票コードを告知することを求めてはならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"総務省は、その処理する事務であつてこの法律の定めるところにより当該事務の処理に関し住民票コードの提供を求めることができることとされているものの遂行のため必要がある場合を除き、何人に対しても、その者又はその者以外の者に係る住民票に記載された住民票コードを告知することを求めてはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"6f3cdc18e80e"},{"num":"30_38","title":"第三十条の三十八","caption":"（住民票コードの利用制限等）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"市町村長、都道府県知事、機構又は総務省（以下この条において「市町村長等」という。）以外の者は、何人も、自己と同一の世帯に属する者以外の者（以下この条において「第三者」という。）に対し、当該第三者又は当該第三者以外の者に係る住民票に記載された住民票コードを告知することを求めてはならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"市町村長等以外の者は、何人も、その者が業として行う行為に関し、その者に対し売買、貸借、雇用その他の契約（以下この項において「契約」という。）の申込みをしようとする第三者若しくは申込みをする第三者又はその者と契約の締結をした第三者に対し、当該第三者又は当該第三者以外の者に係る住民票に記載された住民票コードを告知することを求めてはならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"市町村長等以外の者は、何人も、業として、住民票コードの記録されたデータベース（第三者に係る住民票に記載された住民票コードを含む当該第三者に関する情報の集合物であつて、それらの情報を電子計算機を用いて検索することができるように体系的に構成したものをいう。以下この項において同じ。）であつて、当該データベースに記録された情報が他に提供されることが予定されているものを構成してはならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"都道府県知事は、前二項の規定に違反する行為が行われた場合において、当該行為をした者が更に反復してこれらの規定に違反する行為をするおそれがあると認めるときは、当該行為をした者に対し、当該行為を中止することを勧告し、又は当該行為が中止されることを確保するために必要な措置を講ずることを勧告することができる。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"都道府県知事は、前項の規定による勧告を受けた者がその勧告に従わないときは、第三十条の四十第一項に規定する都道府県の審議会の意見を聴いて、その者に対し、期限を定めて、当該勧告に従うべきことを命ずることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"4ce438b0ac8a"},{"num":"30_39","title":"第三十条の三十九","caption":"（報告及び検査）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"都道府県知事は、前条第四項又は第五項の規定による措置に関し必要があると認めるときは、その必要と認められる範囲内において、同条第二項又は第三項の規定に違反していると認めるに足りる相当の理由がある者に対し、必要な事項に関し報告を求め、又はその職員に、これらの規定に違反していると認めるに足りる相当の理由がある者の事務所若しくは事業所に立ち入り、帳簿、書類その他の物件を検査させることができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定により立入検査をする職員は、その身分を示す証明書を携帯し、関係人の請求があつたときは、これを提示しなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"第一項の規定による立入検査の権限は、犯罪捜査のために認められたものと解釈してはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"977b2310e526"},{"num":"30_40","title":"第三十条の四十","caption":"（都道府県の審議会の設置）","path":["第四章の二　本人確認情報の処理及び利用等","第四節　本人確認情報の保護"],"paras":[{"n":"1","s":[{"t":"都道府県に、第三十条の六第一項の規定による通知に係る本人確認情報の保護に関する審議会（以下この条において「都道府県の審議会」という。）を置く。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"都道府県の審議会は、この法律の規定（次章を除く。）によりその権限に属させられた事項を調査審議するほか、都道府県知事の諮問に応じ、当該都道府県における第三十条の六第一項の規定による通知に係る本人確認情報の保護に関する事項を調査審議し、及びこれらの事項に関して都道府県知事に建議することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"都道府県の審議会の組織及び運営に関し必要な事項は、条例で定める。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"8233199e4b74"},{"num":"30_41","title":"第三十条の四十一","caption":"（市町村長から都道府県知事への附票本人確認情報の通知等）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"市町村長は、戸籍の附票の記載、消除又は第十七条第二号から第三号まで及び第五号から第七号までに掲げる事項の全部若しくは一部についての記載の修正を行つた場合には、当該戸籍の附票の記載等に係る附票本人確認情報（戸籍の附票に記載されている同条第二号から第三号まで及び第五号から第七号までに掲げる事項（戸籍の附票の消除を行つた場合には、当該戸籍の附票に記載されていたこれらの事項）並びに戸籍の附票の記載等に関する事項で政令で定めるものをいう。以下同じ。）を都道府県知事に通知するものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定による通知は、総務省令で定めるところにより、市町村長の使用に係る電子計算機から電気通信回線を通じて都道府県知事の使用に係る電子計算機に送信することによつて行うものとする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"第一項の規定による通知を受けた都道府県知事は、総務省令で定めるところにより、当該通知に係る附票本人確認情報を磁気ディスクに記録し、これを当該通知の日から政令で定める期間保存しなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"都道府県知事は、前項の規定により都道府県知事が保存する附票本人確認情報であつて同項の規定による保存期間が経過していないもの（以下「都道府県知事保存附票本人確認情報」という。）の全部又は一部が滅失したときは、当該都道府県知事保存附票本人確認情報の回復に必要な措置を講じなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"4322c2bfb877"},{"num":"30_42","title":"第三十条の四十二","caption":"（都道府県知事から機構への附票本人確認情報の通知等）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"都道府県知事は、前条第一項の規定による通知に係る附票本人確認情報を、機構に通知するものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定による通知は、総務省令で定めるところにより、都道府県知事の使用に係る電子計算機から電気通信回線を通じて機構の使用に係る電子計算機に送信することによつて行うものとする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"第一項の規定による通知を受けた機構は、総務省令で定めるところにより、当該通知に係る附票本人確認情報を磁気ディスクに記録し、これを当該通知の日から政令で定める期間保存しなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"機構は、前項の規定により機構が保存する附票本人確認情報であつて同項の規定による保存期間が経過していないもの（以下「機構保存附票本人確認情報」という。）の全部又は一部が滅失したときは、当該機構保存附票本人確認情報の回復に必要な措置を講じなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"0c7c1bbc1189"},{"num":"30_43","title":"第三十条の四十三","caption":"（附票本人確認情報の誤りに関する機構の通報）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、その事務を管理し、又は執行するに当たつて、都道府県知事保存附票本人確認情報に誤りがあることを知つたときは、遅滞なく、その旨を当該都道府県知事保存附票本人確認情報を保存する都道府県知事に通報するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"63c369779cc3"},{"num":"30_44","title":"第三十条の四十四","caption":"（国の機関等への附票本人確認情報の提供）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、別表第一の上欄に掲げる国の機関又は法人から同表の下欄に掲げる事務の処理であつて国外転出者に係るものに関し求めがあつたときは、政令で定めるところにより、機構保存附票本人確認情報のうち住民票コード以外のものを提供するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"301474a5db70"},{"num":"30_44_2","title":"第三十条の四十四の二","caption":"（デジタル庁への住民票コードの提供）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、デジタル庁から番号利用法第二十一条第二項又は第二十一条の二第一項（これらの規定を番号利用法第二十六条において準用する場合を含む。）の規定による事務の処理であつて国外転出者に係るものに関し求めがあつたときは、政令で定めるところにより、当該求めに係る者の戸籍の附票に記載された住民票コードを提供するものとする。","kind":"plain"},{"t":"この場合において、機構は、機構保存附票本人確認情報を利用することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"af9986eec8d2"},{"num":"30_44_3","title":"第三十条の四十四の三","caption":"（附票通知都道府県の区域内の市町村の執行機関への附票本人確認情報の提供）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、次の各号のいずれかに該当する場合には、政令で定めるところにより、附票本人確認情報を第三十条の四十二第一項の規定により通知した都道府県知事が統括する都道府県（以下「附票通知都道府県」という。）の区域内の市町村の市町村長その他の執行機関に対し、機構保存附票本人確認情報（第一号及び第二号に掲げる場合にあつては、住民票コードを除く。）を提供するものとする。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"附票通知都道府県の区域内の市町村の市町村長その他の執行機関であつて別表第二の上欄に掲げるものから同表の下欄に掲げる事務の処理であつて国外転出者に係るものに関し求めがあつたとき。","kind":"plain"}]},{"n":"二","s":[{"t":"附票通知都道府県の区域内の市町村の市町村長その他の執行機関から番号利用法第九条第二項の規定に基づき条例で定める事務の処理であつて国外転出者に係るものに関し求めがあつたとき。","kind":"plain"}]},{"n":"三","s":[{"t":"附票通知都道府県の区域内の市町村の市町村長から戸籍の附票に関する事務の処理に関し求めがあつたとき。","kind":"plain"}]}]},{"n":"２","s":[{"t":"前項（第三号に係る部分に限る。）の規定による附票通知都道府県の区域内の市町村の市町村長への機構保存附票本人確認情報の提供は、総務省令で定めるところにより、機構の使用に係る電子計算機から電気通信回線を通じて当該市町村長の使用に係る電子計算機に送信することによつて行うものとする。","kind":"main"},{"t":"ただし、特別の求めがあつたときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"890c7fe3d491"},{"num":"30_44_4","title":"第三十条の四十四の四","caption":"（附票通知都道府県以外の都道府県の執行機関への附票本人確認情報の提供）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、次の各号のいずれかに該当する場合には、政令で定めるところにより、附票通知都道府県以外の都道府県の都道府県知事その他の執行機関に対し、機構保存附票本人確認情報（第一号及び第二号に掲げる場合にあつては、住民票コードを除く。）を提供するものとする。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"附票通知都道府県以外の都道府県の都道府県知事その他の執行機関であつて別表第三の上欄に掲げるものから同表の下欄に掲げる事務の処理であつて国外転出者に係るものに関し求めがあつたとき。","kind":"plain"}]},{"n":"二","s":[{"t":"附票通知都道府県以外の都道府県の都道府県知事その他の執行機関から番号利用法第九条第二項の規定に基づき条例で定める事務の処理であつて国外転出者に係るものに関し求めがあつたとき。","kind":"plain"}]},{"n":"三","s":[{"t":"附票通知都道府県以外の都道府県の都道府県知事から第三十条の四十四の十一第二項の規定による事務の処理に関し求めがあつたとき。","kind":"plain"}]}]},{"n":"２","s":[{"t":"前項（第三号に係る部分に限る。）の規定による附票通知都道府県以外の都道府県の都道府県知事への機構保存附票本人確認情報の提供は、総務省令で定めるところにより、機構の使用に係る電子計算機から電気通信回線を通じて当該都道府県知事の使用に係る電子計算機に送信することによつて行うものとする。","kind":"main"},{"t":"ただし、特別の求めがあつたときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"1444f5908576"},{"num":"30_44_5","title":"第三十条の四十四の五","caption":"（附票通知都道府県以外の都道府県の区域内の市町村の執行機関への附票本人確認情報の提供）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、次の各号のいずれかに該当する場合には、政令で定めるところにより、附票通知都道府県以外の都道府県の区域内の市町村の市町村長その他の執行機関に対し、機構保存附票本人確認情報（第一号及び第二号に掲げる場合にあつては、住民票コードを除く。）を提供するものとする。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"附票通知都道府県以外の都道府県の区域内の市町村の市町村長その他の執行機関であつて別表第四の上欄に掲げるものから附票通知都道府県以外の都道府県の都道府県知事を経て同表の下欄に掲げる事務の処理であつて国外転出者に係るものに関し求めがあつたとき。","kind":"plain"}]},{"n":"二","s":[{"t":"附票通知都道府県以外の都道府県の区域内の市町村の市町村長その他の執行機関から番号利用法第九条第二項の規定に基づき条例で定める事務の処理であつて国外転出者に係るものに関し求めがあつたとき。","kind":"plain"}]},{"n":"三","s":[{"t":"附票通知都道府県以外の都道府県の区域内の市町村の市町村長から附票通知都道府県以外の都道府県の都道府県知事を経て戸籍の附票に関する事務の処理に関し求めがあつたとき。","kind":"plain"}]}]},{"n":"２","s":[{"t":"前項（第三号に係る部分に限る。）の規定による附票通知都道府県以外の都道府県の区域内の市町村の市町村長への機構保存附票本人確認情報の提供は、総務省令で定めるところにより、機構の使用に係る電子計算機から電気通信回線を通じて当該市町村長の使用に係る電子計算機に送信することによつて行うものとする。","kind":"main"},{"t":"ただし、特別の求めがあつたときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"755913c97741"},{"num":"30_44_6","title":"第三十条の四十四の六","caption":"（附票本人確認情報の利用）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"都道府県知事は、次の各号のいずれかに該当する場合には、都道府県知事保存附票本人確認情報（住民票コードを除く。次項並びに次条第二項及び第三項において同じ。）を利用することができる。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"別表第五に掲げる事務を遂行するとき（国外転出者に係る事務を処理する場合に限る。）。","kind":"plain"}]},{"n":"二","s":[{"t":"条例で定める事務を遂行するとき（国外転出者に係る事務を処理する場合に限る。）。","kind":"plain"}]},{"n":"三","s":[{"t":"附票本人確認情報の利用につき当該附票本人確認情報に係る本人が同意した事務を遂行するとき（国外転出者に係る事務を処理する場合に限る。）。","kind":"plain"}]},{"n":"四","s":[{"t":"統計資料（国外転出者に係るものに限る。）の作成を行うとき。","kind":"plain"}]}]},{"n":"２","s":[{"t":"都道府県知事は、次の各号のいずれかに該当する場合には、第一号に掲げる場合にあつては政令で定めるところにより、第二号に掲げる場合にあつては条例で定めるところにより、都道府県知事以外の当該都道府県の執行機関に対し、都道府県知事保存附票本人確認情報を提供するものとする。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"都道府県知事以外の当該都道府県の執行機関であつて別表第六の上欄に掲げるものから同表の下欄に掲げる事務の処理であつて国外転出者に係るものに関し求めがあつたとき。","kind":"plain"}]},{"n":"二","s":[{"t":"都道府県知事以外の当該都道府県の執行機関であつて条例で定めるものから条例で定める事務の処理であつて国外転出者に係るものに関し求めがあつたとき。","kind":"plain"}]}]},{"n":"３","s":[{"t":"都道府県知事は、都道府県知事保存附票本人確認情報（住民票コードに限る。）を、第三十条の十五第一項若しくは第二項又は第三十条の十五の二第二項若しくは第三項の規定による事務（これらの規定により、前二項又は次条第二項若しくは第三項の規定により利用し、又は提供する都道府県知事保存附票本人確認情報に係る者の個人番号を利用し、又は提供する場合に限る。）に利用することができる。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"機構は、都道府県知事から第三十条の六第四項の規定による事務の処理に関し求めがあつたときは、政令で定めるところにより、当該都道府県知事に対し、機構保存附票本人確認情報を提供するものとする。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"機構は、機構保存附票本人確認情報を、第三十条の七第四項又は第三十条の二十二第三項の規定による事務に利用することができる。","kind":"plain"}],"items":[]},{"n":"６","s":[{"t":"機構は、機構保存附票本人確認情報（住民票コードに限る。）を、第三十条の九、第三十条の十から第三十条の十二まで又は第三十条の十五の二第一項の規定による事務（これらの規定により、第三十条の四十四、前三条又は次条第一項の規定により提供される機構保存附票本人確認情報に係る者の個人番号を提供する場合に限る。）に利用することができる。","kind":"plain"}],"items":[]},{"n":"７","s":[{"t":"機構は、機構保存附票本人確認情報を、電子署名等に係る地方公共団体情報システム機構の認証業務に関する法律第八条、第十二条、第十三条、第十八条第三項、第二十七条、第三十条、第三十一条及び第三十四条第二項の規定による事務の処理であつて国外転出者に係るものに利用することができる。","kind":"plain"}],"items":[]},{"n":"８","s":[{"t":"機構は、機構保存附票本人確認情報を、番号利用法第三十八条の二第一項に規定する機構処理事務のうち総務省令で定めるものの処理であつて国外転出者に係るものに利用することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e903c7e86829"},{"num":"30_44_7","title":"第三十条の四十四の七","caption":"（準法定事務処理者への附票本人確認情報の提供等）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、準法定事務処理者から第三十条の十五の二第一項に規定する総務省令で定める準法定事務の処理であつて国外転出者に係るものに関し求めがあつたときは、政令で定めるところにより、機構保存附票本人確認情報のうち住民票コード以外のものを提供するものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"都道府県知事は、第三十条の十五の二第二項に規定する総務省令で定める準法定事務を遂行するとき（国外転出者に係る事務を処理する場合に限る。）は、都道府県知事保存附票本人確認情報を利用することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"都道府県知事は、第三十条の十五の二第三項に規定する総務省令で定める者から同項に規定する総務省令で定める準法定事務の処理であつて国外転出者に係るものに関し求めがあつたときは、都道府県知事保存附票本人確認情報を提供するものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"37d4295b8a27"},{"num":"30_44_8","title":"第三十条の四十四の八","caption":"（報告書の公表）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、毎年少なくとも一回、第三十条の四十四、第三十条の四十四の二及び前条第一項（準法定事務処理者（国の機関又は別表第一の上欄に掲げる法人に限る。第三十条の四十四の十二において同じ。）への機構保存附票本人確認情報の提供に係る部分に限る。）の規定による機構保存附票本人確認情報及び住民票コードの提供の状況について、総務省令で定めるところにより、報告書を作成し、これを公表しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"05614e2d454c"},{"num":"30_44_9","title":"第三十条の四十四の九","caption":"（本人確認情報処理事務に関する規定の準用）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"第三十条の十七から第三十条の二十までの規定は、この章の規定により機構が処理することとされている事務について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"eff6019ab758"},{"num":"30_44_10","title":"第三十条の四十四の十","caption":"（都道府県知事に対する技術的な助言等）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、都道府県知事に対し、第三十条の四十一第一項の規定による通知に係る附票本人確認情報の電子計算機処理に関し必要な技術的な助言及び情報の提供を行うものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ae1f92081a35"},{"num":"30_44_11","title":"第三十条の四十四の十一","caption":"（市町村間の連絡調整等）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"都道府県知事は、第三十条の四十一第二項の規定による電気通信回線を通じた附票本人確認情報の送信その他この章に規定する市町村の事務の処理に関し、当該都道府県の区域内の市町村相互間における必要な連絡調整を行うものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"都道府県知事は、当該都道府県の区域内の市町村の市町村長に対し、戸籍の附票に正確な記録が行われるよう、必要な協力をするものとする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"機構は、都道府県知事に対し、当該都道府県の区域内の市町村が備える戸籍の附票に正確な記録が行われるよう、必要な協力をしなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ca1b2b9787e9"},{"num":"30_44_12","title":"第三十条の四十四の十二","caption":"（附票本人確認情報の提供に関する手数料）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"機構は、第三十条の四十四、第三十条の四十四の二又は第三十条の四十四の七第一項に規定する求めを行う別表第一の上欄に掲げる国の機関若しくは法人若しくは準法定事務処理者又はデジタル庁から、総務大臣の認可を受けて定める額の手数料を徴収することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ab2bd8604fa1"},{"num":"30_44_13","title":"第三十条の四十四の十三","caption":"（附票本人確認情報の保護）","path":["第四章の三　附票本人確認情報の処理及び利用等"],"paras":[{"n":"1","s":[{"t":"前章第四節（第三十条の三十七から第三十条の三十九までを除く。）の規定は、附票本人確認情報の保護について準用する。","kind":"plain"},{"t":"この場合において、これらの規定中「受領者」とあるのは「附票情報受領者」と、「受領した本人確認情報等」とあるのは「受領した附票本人確認情報等」と読み替えるほか、次の表の上欄に掲げる規定中同表の中欄に掲げる字句は、それぞれ同表の下欄に掲げる字句に読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c3b9998b7186"},{"num":"30_45","title":"第三十条の四十五","caption":"（外国人住民に係る住民票の記載事項の特例）","path":["第四章の四　外国人住民に関する特例"],"paras":[{"n":"1","s":[{"t":"日本の国籍を有しない者のうち次の表の上欄に掲げるものであつて市町村の区域内に住所を有するもの（以下「外国人住民」という。）に係る住民票には、第七条の規定にかかわらず、同条各号（第一号の二、第五号、第六号及び第九号を除く。）に掲げる事項、国籍等（国籍の属する国又は出入国管理及び難民認定法（昭和二十六年政令第三百十九号。以下この章において「入管法」という。）第二条第五号ロに規定する地域をいう。以下同じ。）、外国人住民となつた年月日（外国人住民が同表の上欄に掲げる者となつた年月日又は住民となつた年月日のうち、いずれか遅い年月日をいう。以下同じ。）及び同表の上欄に掲げる者の区分に応じそれぞれ同表の下欄に掲げる事項について記載をする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"9ede370c9ea2"},{"num":"30_46","title":"第三十条の四十六","caption":"（中長期在留者等が住所を定めた場合の転入届の特例）","path":["第四章の四　外国人住民に関する特例"],"paras":[{"n":"1","s":[{"t":"前条の表の上欄に掲げる者（出生による経過滞在者又は国籍喪失による経過滞在者を除く。以下この条及び次条において「中長期在留者等」という。）が国外から転入をした場合（これに準ずる場合として総務省令で定める場合を含む。）には、当該中長期在留者等は、第二十二条の規定にかかわらず、転入をした日から十四日以内に、同条第一項第一号、第二号及び第五号に掲げる事項、出生の年月日、男女の別、国籍等、外国人住民となつた年月日並びに同表の上欄に掲げる者の区分に応じそれぞれ同表の下欄に掲げる事項を市町村長に届け出なければならない。","kind":"plain"},{"t":"この場合において、当該中長期在留者等は、市町村長に対し、同表の上欄に掲げる者の区分に応じそれぞれ同表の下欄に規定する在留カード、特別永住者証明書又は仮滞在許可書（一時庇護許可者にあつては、入管法第十八条の二第三項に規定する一時庇護許可書）を提示しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"4e18fdbd2367"},{"num":"30_47","title":"第三十条の四十七","caption":"（住所を有する者が中長期在留者等となつた場合の届出）","path":["第四章の四　外国人住民に関する特例"],"paras":[{"n":"1","s":[{"t":"日本の国籍を有しない者（第三十条の四十五の表の上欄に掲げる者を除く。）で市町村の区域内に住所を有するものが中長期在留者等となつた場合には、当該中長期在留者等となつた者は、中長期在留者等となつた日から十四日以内に、第二十二条第一項第一号、第二号及び第五号に掲げる事項、出生の年月日、男女の別、国籍等、外国人住民となつた年月日並びに同表の上欄に掲げる者の区分に応じそれぞれ同表の下欄に掲げる事項を市町村長に届け出なければならない。","kind":"plain"},{"t":"この場合においては、前条後段の規定を準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"27b4b665c115"},{"num":"30_48","title":"第三十条の四十八","caption":"（外国人住民の世帯主との続柄の変更の届出）","path":["第四章の四　外国人住民に関する特例"],"paras":[{"n":"1","s":[{"t":"第二十二条第一項、第二十三条、第二十五条及び前二条の場合を除くほか、世帯主でない外国人住民であつてその世帯主（外国人住民であるものに限る。）との続柄に変更があつたものは、その変更があつた日から十四日以内に、世帯主との続柄を証する文書を添えて、その氏名、世帯主との続柄及び変更があつた年月日を市町村長に届け出なければならない。","kind":"main"},{"t":"ただし、政令で定める場合にあつては、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"0fdb755ee662"},{"num":"30_49","title":"第三十条の四十九","caption":"（外国人住民の世帯主との続柄を証する文書の提出）","path":["第四章の四　外国人住民に関する特例"],"paras":[{"n":"1","s":[{"t":"世帯主でない外国人住民であつてその世帯主が外国人住民であるものは、第二十二条第一項、第二十三条、第二十五条、第三十条の四十六又は第三十条の四十七の規定による届出をするときは、世帯主との続柄を証する文書を添えて、これらの規定に規定する届出をしなければならない。","kind":"main"},{"t":"ただし、政令で定める場合にあつては、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"cd9d2ddbb2d9"},{"num":"30_50","title":"第三十条の五十","caption":"（外国人住民に係る住民票の記載の修正等のための出入国在留管理庁長官からの通知）","path":["第四章の四　外国人住民に関する特例"],"paras":[{"n":"1","s":[{"t":"出入国在留管理庁長官は、入管法及び入管特例法に定める事務を管理し、又は執行するに当たつて、外国人住民についての第七条第一号、第二号及び第三号に掲げる事項、国籍等又は第三十条の四十五の表の下欄に掲げる事項に変更があつたこと又は誤りがあることを知つたときは、遅滞なく、その旨を当該外国人住民が記録されている住民基本台帳を備える市町村の市町村長に通知しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e11707deb9b8"},{"num":"30_51","title":"第三十条の五十一","caption":"（外国人住民についての適用の特例）","path":["第四章の四　外国人住民に関する特例"],"paras":[{"n":"1","s":[{"t":"外国人住民に係る次の表の上欄に掲げる規定の適用については、これらの規定中同表の中欄に掲げる字句は、それぞれ同表の下欄に掲げる字句とする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"718d59f9a743"},{"num":"31","title":"第三十一条","caption":"（国又は都道府県の指導等）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"国は都道府県及び市町村に対し、都道府県は市町村に対し、この法律の目的を達成するため、この法律の規定により都道府県又は市町村が処理する事務について、必要な指導を行うものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"主務大臣は都道府県知事又は市町村長に対し、都道府県知事は市町村長に対し、前項の事務に関し必要があると認めるときは、報告を求め、又は助言若しくは勧告をすることができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"主務大臣は、前項の規定による助言又は勧告をしようとするときは、国民健康保険の被保険者、後期高齢者医療の被保険者、介護保険の被保険者及び国民年金の被保険者に関する事項については厚生労働大臣、児童手当の支給を受けている者に関する事項については内閣総理大臣、米穀の配給を受ける者に関する事項については農林水産大臣に協議するものとする。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"都道府県知事は主務大臣に対し、市町村長は主務大臣又は都道府県知事に対し、第二項の規定による助言又は勧告を求めることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"f783d9396390"},{"num":"32","title":"第三十二条","caption":"（行政手続法の適用除外）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"この法律の規定により市町村長がする処分については、行政手続法（平成五年法律第八十八号）第二章及び第三章の規定は、適用しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c632c1ff7fd5"},{"num":"33","title":"第三十三条","caption":"（関係市町村長の意見が異なる場合の措置）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"市町村長は、住民の住所の認定について他の市町村長と意見を異にし、その協議がととのわないときは、都道府県知事（関係市町村が二以上の都道府県の区域内の市町村である場合には、主務大臣）に対し、その決定を求める旨を申し出なければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"主務大臣又は都道府県知事は、前項の申出を受けた場合には、その申出を受けた日から六十日以内に決定をしなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前項の決定は、文書をもつてし、その理由を附して関係市町村長に通知しなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"関係市町村長は、第二項の決定に不服があるときは、前項の通知を受けた日から三十日以内に裁判所に出訴することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"0025750e9973"},{"num":"34","title":"第三十四条","caption":"（調査）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"市町村長は、定期に、第七条及び第三十条の四十五の規定により記載をすべきものとされる事項について調査をするものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"市町村長は、前項に定める場合のほか、必要があると認めるときは、いつでも第七条及び第三十条の四十五の規定により記載をすべきものとされる事項について調査をすることができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"市町村長は、前二項の調査に当たり、必要があると認めるときは、当該職員をして、関係人に対し、質問をさせ、又は文書の提示を求めさせることができる。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"当該職員は、前項の規定により質問をし、又は文書の提示を求める場合には、その身分を示す証明書を携帯し、関係人の請求があつたときは、これを提示しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"7b8ac537333c"},{"num":"35","title":"第三十五条","caption":"（秘密を守る義務）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"住民基本台帳に関する調査に関する事務に従事している者又は従事していた者は、その事務に関して知り得た秘密を漏らしてはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a1d4db661f53"},{"num":"36","title":"第三十六条","caption":"（住民に関する記録の保護）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"市町村長の委託（二以上の段階にわたる委託を含む。）を受けて行う住民基本台帳又は戸籍の附票に関する事務の処理に従事している者又は従事していた者は、その事務に関して知り得た事項をみだりに他人に知らせ、又は不当な目的に使用してはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"bed8870a6ac8"},{"num":"36_2","title":"第三十六条の二","caption":"（住民票に記載されている事項の安全確保等）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"市町村長は、住民基本台帳又は戸籍の附票に関する事務の処理に当たつては、住民票、除票、戸籍の附票又は戸籍の附票の除票に記載されている事項の漏えい、滅失及び毀損の防止その他の住民票、除票、戸籍の附票又は戸籍の附票の除票に記載されている事項の適切な管理のために必要な措置を講じなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、市町村長から住民基本台帳又は戸籍の附票に関する事務の処理の委託（二以上の段階にわたる委託を含む。）を受けた者が受託した業務を行う場合について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"0da9eca8b821"},{"num":"36_3","title":"第三十六条の三","caption":"（苦情処理）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"市町村長は、この法律の規定により市町村が処理する事務の実施に関する苦情の適切かつ迅速な処理に努めなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"39fb0859f873"},{"num":"37","title":"第三十七条","caption":"（資料の提供）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"国の行政機関又は都道府県知事は、それぞれの所掌事務について必要があるときは、市町村長に対し、住民基本台帳に記録されている事項又は除票に記載されている事項に関して資料の提供を求めることができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"国の行政機関は、その所掌事務について必要があるときは、都道府県知事又は機構に対し、それぞれ都道府県知事保存本人確認情報又は機構保存本人確認情報に関して資料の提供を求めることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"9951028a56e7"},{"num":"38","title":"第三十八条","caption":"（指定都市の特例）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"地方自治法第二百五十二条の十九第一項の指定都市（以下「指定都市」という。）に対するこの法律の規定で政令で定めるものの適用については、区及び総合区を市と、区及び総合区の区域を市の区域と、区長及び総合区長を市長とみなす。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項に定めるもののほか、指定都市に対するこの法律の規定の適用については、政令で特別の定めをすることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"1a1560a3a514"},{"num":"39","title":"第三十九条","caption":"（適用除外等）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"この法律は、日本の国籍を有しない者のうち第三十条の四十五の表の上欄に掲げる者以外のもの、戸籍法の適用を受けない者（天皇及び皇族以外の男子と婚姻をした内親王及び女王（当該男子と離婚又は死別をした者を含む。）を除く。）その他政令で定める者については、適用しない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項に規定する内親王及び女王に対するこの法律及び電子署名等に係る地方公共団体情報システム機構の認証業務に関する法律の規定の適用については、政令で特例を定めることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"cc4f1fc9aebb"},{"num":"40","title":"第四十条","caption":"（主務大臣）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"この法律において、主務大臣は、総務大臣とする。","kind":"main"},{"t":"ただし、第九条第二項の規定による通知に関する事項及び第三章に規定する戸籍の附票に関する事項については、総務大臣及び法務大臣とする。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"8a4c772181de"},{"num":"41","title":"第四十一条","caption":"（政令への委任）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"この法律の実施のための手続その他その施行に関し必要な事項は、政令で定める。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a15a8bf594bb"},{"num":"41_2","title":"第四十一条の二","caption":"（事務の区分）","path":["第五章　雑則"],"paras":[{"n":"1","s":[{"t":"第十九条の三の規定により市町村が処理することとされている事務は、地方自治法第二条第九項第一号に規定する第一号法定受託事務とする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"419ee2ce0cfc"},{"num":"42","title":"第四十二条","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"第三十条の二十六又は第三十条の三十（これらの規定を第三十条の四十四の十三において準用する場合を含む。）の規定に違反して秘密を漏らした者は、二年以下の拘禁刑又は百万円以下の罰金に処する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"0908a7d3ebe5"},{"num":"43","title":"第四十三条","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"次の各号のいずれかに該当する者は、一年以下の拘禁刑又は五十万円以下の罰金に処する。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"第三十条の三十八第五項の規定による命令に違反した者","kind":"plain"}]},{"n":"二","s":[{"t":"次に掲げる者であつて、その事務に関して知り得た事項を自己又は第三者の不正な利益を図る目的で提供し、又は盗用したもの","kind":"plain"}],"items":[{"n":"イ","s":[{"t":"住民基本台帳又は戸籍の附票に関する事務に従事する市町村の職員又は職員であつた者","kind":"plain"}]},{"n":"ロ","s":[{"t":"市町村長の委託（二以上の段階にわたる委託を含む。）を受けて行う住民基本台帳又は戸籍の附票に関する事務の処理に従事している者又は従事していた者","kind":"plain"}]},{"n":"ハ","s":[{"t":"第三十条の六第一項の規定による通知に係る本人確認情報又は第三十条の四十一第一項の規定による通知に係る附票本人確認情報の電子計算機処理等に関する事務に従事する都道府県の職員又は職員であつた者","kind":"plain"}]},{"n":"ニ","s":[{"t":"都道府県知事の委託（二以上の段階にわたる委託を含む。）を受けて行う第三十条の六第一項の規定による通知に係る本人確認情報又は第三十条の四十一第一項の規定による通知に係る附票本人確認情報の電子計算機処理等に関する事務に従事している者又は従事していた者","kind":"plain"}]},{"n":"ホ","s":[{"t":"本人確認情報又は附票本人確認情報の電子計算機処理等に関する事務に従事する機構の役員若しくは職員又はこれらの職にあつた者","kind":"plain"}]},{"n":"ヘ","s":[{"t":"機構の委託（二以上の段階にわたる委託を含む。）を受けて行う第三十条の七第一項の規定による通知に係る本人確認情報又は第三十条の四十二第一項の規定による通知に係る附票本人確認情報の電子計算機処理等に関する事務に従事している者又は従事していた者","kind":"plain"}]},{"n":"ト","s":[{"t":"受領した本人確認情報等又は受領した附票本人確認情報等の電子計算機処理等に関する事務に従事する受領者又は第三十条の四十四の十三において準用する第三十条の二十八第一項に規定する附票情報受領者（チにおいて「附票情報受領者」という。）の職員又は職員であつた者","kind":"plain"}]},{"n":"チ","s":[{"t":"受領者又は附票情報受領者の委託（二以上の段階にわたる委託を含む。）を受けて行う受領した本人確認情報等又は第三十条の四十四の十三において準用する第三十条の二十八第一項に規定する受領した附票本人確認情報等の電子計算機処理等に関する事務に従事している者又は従事していた者","kind":"plain"}]}]}]}],"proviso":false,"deleted":false,"h":"5f3eae9ae795"},{"num":"44","title":"第四十四条","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"第三十五条の規定に違反して秘密を漏らした者は、一年以下の拘禁刑又は三十万円以下の罰金に処する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"455b0931ef53"},{"num":"45","title":"第四十五条","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"第十一条の二第九項又は第十項の規定による命令に違反した者は、六月以下の拘禁刑又は三十万円以下の罰金に処する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"eea0c0a1c7f9"},{"num":"46","title":"第四十六条","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"次の各号のいずれかに該当する者は、三十万円以下の罰金に処する。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"第十一条の二第十一項若しくは第三十条の三十九第一項の規定による報告をせず、若しくは虚偽の報告をし、又は同項の規定による検査を拒み、妨げ、若しくは忌避した者","kind":"plain"}]},{"n":"二","s":[{"t":"偽りその他不正の手段により、第十二条から第十二条の三まで（これらの規定を第三十条の五十一の規定により読み替えて適用する場合を含む。）に規定する住民票の写し若しくは住民票記載事項証明書の交付を受け、第十二条の四（第三十条の五十一の規定により読み替えて適用する場合を含む。）に規定する住民票の写しの交付を受け、第十五条の四（第三十条の五十一の規定により読み替えて適用する場合を含む。）に規定する除票の写し若しくは除票記載事項証明書の交付を受け、第二十条に規定する戸籍の附票の写しの交付を受け、又は第二十一条の三に規定する戸籍の附票の除票の写しの交付を受けた者","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"d6449282993b"},{"num":"47","title":"第四十七条","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"次の各号のいずれかに該当するときは、その違反行為をした機構の役員又は職員は、三十万円以下の罰金に処する。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"第三十条の十八（第三十条の四十四の九において準用する場合を含む。）の規定に違反して帳簿を備えず、帳簿に記載せず、若しくは帳簿に虚偽の記載をし、又は帳簿を保存しなかつたとき。","kind":"plain"}]},{"n":"二","s":[{"t":"第三十条の二十第一項（第三十条の四十四の九において準用する場合を含む。以下この号において同じ。）の規定による報告をせず、若しくは虚偽の報告をし、又は同項の規定による検査を拒み、妨げ、若しくは忌避したとき。","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"969433baa281"},{"num":"48","title":"第四十八条","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"法人（法人でない団体で代表者又は管理人の定めのあるものを含む。以下この項において同じ。）の代表者若しくは管理人又は法人若しくは人の代理人、使用人その他の従事者が、その法人又は人の業務に関して第四十三条第一号、第四十五条又は第四十六条第一号の違反行為をしたときは、その行為者を罰するほか、その法人又は人に対し各本条の罰金刑を科する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"法人でない団体について前項の規定の適用がある場合には、その代表者又は管理人が、その訴訟行為につき法人でない団体を代表するほか、法人を被告人又は被疑者とする場合の刑事訴訟に関する法律の規定を準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c33fe360c168"},{"num":"49","title":"第四十九条","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"第三十四条第三項の規定による質問に対し、答弁をせず、若しくは虚偽の陳述をし、又は文書の提示を拒み、妨げ、忌避し、若しくは虚偽の文書を提示した者は、五万円以下の罰金に処する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"32da19b3dd15"},{"num":"49_2","title":"第四十九条の二","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"第四十二条（第三十条の三十第二項（第三十条の四十四の十三において準用する場合を含むものとし、別表第一の四十一の項の下欄に掲げる事務の処理に関し外務省が提供を受けた本人確認情報又は附票本人確認情報の電子計算機処理等に関する事務に従事する外務省の職員又は職員であつた者に係る部分に限る。）に係る部分に限る。）及び第四十三条（第二号ト（当該事務に従事する外務省の職員又は職員であつた者に係る部分に限る。）に係る部分に限る。）の規定は、日本国外においてこれらの条の罪を犯した者にも適用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"edace156f95a"},{"num":"50","title":"第五十条","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"偽りその他不正の手段により第十一条の二第一項の規定による住民基本台帳の一部の写しの閲覧をし、若しくはさせた者又は同条第七項の規定に違反して、当該閲覧事項を利用目的以外の目的のために利用し、若しくは当該閲覧事項に係る申出者、閲覧者、個人閲覧事項取扱者及び法人閲覧事項取扱者以外の者に提供した者は、三十万円以下の過料に処する。","kind":"main"},{"t":"ただし、第四十五条の規定により刑を科すべきときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"f92e94a6b899"},{"num":"51","title":"第五十一条","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"偽りその他不正の手段により第三十条の三十二第二項（第三十条の四十四の十三において準用する場合を含む。）の規定による開示を受けた者は、十万円以下の過料に処する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"bf73f5cddbed"},{"num":"52","title":"第五十二条","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"第二十二条から第二十四条まで、第二十五条又は第三十条の四十六から第三十条の四十八までの規定による届出に関し虚偽の届出（第二十八条から第三十条までの規定による付記を含む。）をした者は、他の法令の規定により刑を科すべき場合を除き、五万円以下の過料に処する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"正当な理由がなくて第二十二条から第二十四条まで、第二十五条又は第三十条の四十六から第三十条の四十八までの規定による届出をしない者は、五万円以下の過料に処する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e665ee54f3e9"},{"num":"53","title":"第五十三条","caption":"","path":["第六章　罰則"],"paras":[{"n":"1","s":[{"t":"前三条の規定による過料についての裁判は、簡易裁判所がする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"5daab8c3183e"}]};
